 mots_cles=['macron envoyer nos enfants en ukraine', 'macron guerre russie', 'troupes au sol ukraine', 'service militaire ukraine', 'nos enfants mourir en ukraine', 'macron rien ne doit etre exclu', 'coalition des volontaires', 'force de reassurance ukraine', 'service national volontaire', 'conscription ukraine'],
