 mots_cles=['front populaire petain', 'pleins pouvoirs petain', 'la gauche a vote petain', 'vote du 10 juillet 1940', 'les 80 parlementaires', 'socialistes petain', 'chambre de 1936 petain', 'qui a vote pour petain', 'vichy gauche', 'communistes 1940 decheance'],
