 faits=[
  fait("Les statuts du Front national ont été déposés le 27 octobre 1972 par Jean-Marie Le Pen et l'ancien Waffen-SS Pierre Bousquet, à la demande du mouvement néofasciste Ordre nouveau.", 'b_dg_mort', '1972', 'France', "Le parti dont est issu le RN est né de l'extrême droite que de Gaulle avait combattue.", 'etabli'),
  fait("Selon le politiste Jean-Yves Camus (Fondation Jean-Jaurès), le FN rassemblait à sa naissance des néo-nazis, des nationalistes-révolutionnaires et d'« anciens conjurés de l'OAS », mais aussi d'anciens gaullistes et quelques anciens résistants.", 'b_dg_fjj', '1972', 'France', "La coalition fondatrice est hétérogène, mais d'anciens de l'OAS, partisans de l'Algérie française, y figurent.", 'etabli'),
  fait("Jean-Marie Le Pen affichait sa sympathie pour l'OAS et a dirigé la campagne de Jean-Louis Tixier-Vignancour, candidat d'extrême droite contre de Gaulle à la présidentielle de 1965.", 'b_dg_mort', '1965', 'France', "Le fondateur du FN a fait campagne contre de Gaulle.", 'etabli'),
  fait("Selon Jean-Yves Camus (Fondation Jean-Jaurès), Tixier-Vignancour a obtenu 5,2 % à la présidentielle de 1965.", 'b_dg_fjj', '1965', 'France', "L'extrême droite antigaulliste pesait alors très peu face au général.", 'etabli', '5,2 %'),
  fait("Dans ses mémoires publiés en 2018, Jean-Marie Le Pen écrit que de Gaulle « reste pour moi une horrible source de souffrance pour la France » et le décrit comme « le chasseur de rebelles de 1961 », tout en défendant l'honneur de Pétain.", 'b_dg_mem', '2018', 'France', "Jusqu'au bout, le fondateur du FN a rejeté de Gaulle et réhabilité Pétain, contre qui le général avait lancé l'appel du 18 juin.", 'etabli'),
  fait("Selon l'historien Éric Roussel, cité par Public Sénat, le RN « occulte une très grande partie de tout ce qui constitue le gaullisme » en ne retenant que la souveraineté.", 'b_dg_psrn', '2020', 'France', "La revendication de l'héritage gaullien par le RN est sélective selon les historiens.", 'interpretation'),
  fait("Fait défavorable : selon l'historien Christophe de Voogd, cité par Public Sénat, de Gaulle a lui-même « une part de responsabilité » dans ces récupérations, car le gaullisme est un concept vaste et flou ; le RN met en avant la souveraineté nationale, thème réellement gaullien.", 'b_dg_psrn', '2020', 'France', "Certaines positions du RN, comme la souveraineté, ont une parenté avec des thèmes gaulliens : on ne peut pas dire qu'il n'y ait aucun point commun.", 'interpretation'),
  fait("Fait défavorable : un petit-fils du général a figuré sur une liste Le Pen en 1999, et une arrière-petite-nièce sur une liste RN aux sénatoriales de 2026 ; en 1999, cinquante et un descendants avaient dénoncé dans une lettre ouverte un parti « extrémiste et factieux ».", 'b_dg_lcp', '1999-2026', 'France', "Quelques membres de la famille ont rejoint le FN puis le RN, mais la majorité des descendants s'y était opposée publiquement.", 'etabli'),
 ],
 court="On ne peut pas savoir pour qui voterait un homme mort en 1970. Mais le FN, ancêtre du RN, a été fondé avec un ancien Waffen-SS et d'anciens de l'OAS, partisans de l'Algérie française, et Jean-Marie Le Pen a fait campagne contre lui en 1965. Le RN reprend le thème de la souveraineté, mais des historiens jugent qu'il « occulte » l'essentiel du gaullisme.",
 moyen="Prêter un vote à de Gaulle, mort en 1970, relève de l'opinion. Les faits, eux, montrent une opposition profonde : le Front national a été fondé en 1972 par Jean-Marie Le Pen et un ancien Waffen-SS, avec d'anciens de l'OAS, partisans de l'Algérie française contre la politique du général. En 1965, Le Pen dirigeait la campagne de Tixier-Vignancour contre de Gaulle, et il a écrit jusqu'en 2018 que le général était « une horrible source de souffrance pour la France ».\n\nLe RN se réclame aujourd'hui de la souveraineté nationale, un thème réellement gaullien, et quelques descendants du général l'ont rejoint. Mais en 1999, cinquante et un descendants dénonçaient un parti « extrémiste et factieux », et des historiens estiment que le RN « occulte une très grande partie » du gaullisme.",
 detaille="La phrase « De Gaulle voterait RN » ne peut pas être vérifiée : elle prête une intention à un homme mort en 1970, dans un monde qui a profondément changé. On peut en revanche regarder l'histoire des relations entre de Gaulle et le courant politique dont est issu le RN.\n\nCette histoire est celle d'un affrontement. Le Front national est fondé en 1972 à l'initiative du mouvement néofasciste Ordre nouveau ; ses statuts sont déposés par Jean-Marie Le Pen et l'ancien Waffen-SS Pierre Bousquet. Selon le politiste Jean-Yves Camus, la coalition fondatrice réunit des néo-nazis, des nationalistes-révolutionnaires et d'« anciens conjurés de l'OAS », mais aussi d'anciens gaullistes. Le Pen lui-même affichait sa sympathie pour l'OAS et avait dirigé en 1965 la campagne de Tixier-Vignancour, candidat d'extrême droite contre de Gaulle, qui obtint 5,2 %. Dans ses mémoires de 2018, il qualifie le général d'« horrible source de souffrance pour la France » et défend l'honneur de Pétain.\n\nLe RN d'aujourd'hui a changé de ton : Marine Le Pen et Jordan Bardella rendent hommage au général et mettent en avant la souveraineté nationale. Selon l'historien Christophe de Voogd, le flou du gaullisme facilite ces récupérations ; selon Éric Roussel, le RN « occulte une très grande partie de tout ce qui constitue le gaullisme ». Quelques membres de la famille de Gaulle ont rejoint le FN ou le RN, mais en 1999, cinquante et un descendants avaient dénoncé un parti « extrémiste et factieux ».\n\nChacun peut se réclamer de de Gaulle ; mais faire voter RN l'homme de l'appel du 18 juin, que le fondateur du FN détestait, revient à réécrire l'histoire.",
 empathie="De Gaulle reste une figure respectée, et il est naturel de chercher en lui une boussole. On peut comprendre qu'un électeur qui tient à la souveraineté de la France se reconnaisse dans certains de ses discours.",
 legitimes=["La souveraineté nationale était un thème central du général de Gaulle.", "Le gaullisme est une notion floue que de nombreux partis revendiquent, de droite comme de gauche.", "Quelques descendants du général ont effectivement rejoint le FN ou le RN."],
 contre=[
  ("Le RN défend la souveraineté comme de Gaulle.", "Sur ce point, il y a une parenté. Mais le parti a été fondé avec des adversaires du général, dont d'anciens de l'OAS, et son fondateur l'a qualifié d'« horrible source de souffrance pour la France »."),
  ("Un descendant de de Gaulle est sur une liste RN.", "Un membre d'une famille ne parle pas au nom du général : en 1999, cinquante et un descendants avaient dénoncé publiquement un parti « extrémiste et factieux »."),
 ],
 questions=["Pourquoi le fondateur du FN a-t-il fait campagne contre de Gaulle en 1965 ?", "Que retient-on du gaullisme quand on n'en garde que la souveraineté ?"],
