FICHES.append(fiche(
 id='italiens-portugais-integration-maghrebins', affirmation="Les Italiens et les Portugais se sont intégrés, pas les Maghrébins.", volet='immigration', sous_theme='Intégration',
 mots_cles=['italiens portugais integres', 'les maghrebins ne s integrent pas', 'integration maghrebins', 'immigration europeenne integration', 'aigues mortes', 'ritals', 'descendants d immigres maghreb', 'enquete teo2', 'mariages mixtes maghrebins', 'discrimination maghrebins'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Les Italiens aussi ont été jugés inassimilables : en 1893, des ouvriers italiens ont été massacrés à Aigues-Mortes. Aujourd'hui, les descendants d'immigrés maghrébins progressent nettement par rapport à leurs parents (diplômes, couples mixtes) et, comme les autres descendants, se sentent très majoritairement chez eux en France. Les écarts qui subsistent sont réels, notamment le chômage et les couples mixtes, mais ils vont de pair avec beaucoup plus de discriminations déclarées : 35 % chez les descendants d'origine algérienne, contre 12 % pour l'Europe du Sud.",
 contexte="L'argument oppose une « bonne » immigration européenne, chrétienne, qui se serait fondue dans la population, à une immigration maghrébine qui refuserait de s'intégrer. Il sert souvent à justifier un tri des immigrés selon l'origine ou la religion.",
 explication="On compare ce qui est comparable : l'accueil historique des Italiens, puis les données de la statistique publique sur les descendants d'immigrés (enquête Trajectoires et Origines 2, Insee-Ined) selon l'origine : diplômes, couples, sentiment d'appartenance, emploi, discriminations.",
 sources=[B_IT_HM, B_IT_NOIR, B_IT_MIX, B_IT_DIPL, B_IT_DISC, B_IT_RESS, B_IT_EMP, B_IT_TRANS],
 faits=[
  fait("Selon la revue Hommes & Migrations, éditée par le Musée national de l'histoire de l'immigration, des Italiens ont été « massacrés lors de poussées xénophobes comme à Aigues-Mortes en 1893 ».", 'b_it_hm', '1893', 'France', "L'immigration italienne, aujourd'hui citée en modèle, a d'abord été violemment rejetée.", 'etabli'),
  fait("Selon une fiche de lecture de l'ENS consacrée au livre de l'historien Gérard Noiriel, le bilan d'Aigues-Mortes va d'environ 8 morts selon les autorités françaises à une cinquantaine selon les Italiens, tous les accusés ont été acquittés et la presse diffusait le stéréotype de l'« Italien au couteau ».", 'b_it_noir', '1893', 'France', "Les mêmes accusations de violence et d'inassimilabilité visaient les Italiens ; leur intégration s'est faite sur plusieurs générations.", 'estimation'),
  fait("Selon l'Insee, en 2025, 36,5 % des immigrés du Maghreb ont au plus le brevet, contre 20,0 % de leurs descendants ; pour le Portugal, la part passe de 51,0 % chez les immigrés à 13,1 % chez les descendants ; elle est de 12,6 % chez les personnes sans ascendance migratoire.", 'b_it_dipl', '2025', 'France hors Mayotte, 15-64 ans', "Les descendants d'immigrés maghrébins progressent fortement par rapport à leurs parents, même si l'écart avec les descendants portugais reste visible.", 'etabli', '20,0 %'),
  fait("Selon l'enquête Trajectoires et Origines 2, 95 % des descendants d'immigrés se sentent chez eux en France, contre 93 % des personnes sans ascendance migratoire ; mais 29 % à 30 % des descendants d'origine maghrébine estiment qu'on ne les voit pas comme Français, contre 9 % pour l'Europe du Sud.", 'b_it_ress', '2019-2020', 'France métropolitaine', "Le sentiment d'appartenance est très fort ; c'est le regard des autres qui les tient à distance.", 'etabli', '95 %'),
  fait("Selon l'enquête Trajectoires et Origines 2, 35 % des descendants d'immigrés d'Algérie et 34 % de ceux du Maroc ou de Tunisie déclarent avoir subi des discriminations en cinq ans, contre 12 % des descendants d'Europe du Sud ; le motif de l'origine ou de la couleur de peau est cité par 77 % des descendants d'Algérie concernés.", 'b_it_disc', '2019-2020', 'France métropolitaine', "Les descendants maghrébins ne vivent pas la même société que les descendants européens : ils sont trois fois plus souvent discriminés.", 'etabli', '35 %'),
  fait("Fait défavorable : selon l'Insee, 39 % des descendants d'immigrés du Maghreb vivent en couple avec une personne sans ascendance migratoire, contre 78 % des descendants d'immigrés d'Espagne, d'Italie ou du Portugal ; la part a toutefois plus que doublé par rapport aux immigrés maghrébins (17 %).", 'b_it_mix', '2019-2020', 'France métropolitaine', "Les couples mixtes sont nettement moins fréquents chez les descendants maghrébins : c'est un écart réel, même s'il se réduit d'une génération à l'autre.", 'etabli', '39 %'),
  fait("Fait défavorable : selon l'Insee, entre 2013 et 2018, le taux de chômage était de 24 % chez les hommes descendants d'immigrés du Maghreb et de 18 % chez les femmes, contre 9 % pour les descendants d'Europe du Sud et 8 % pour les personnes sans ascendance migratoire ; pour les hommes, environ 10 points d'écart ne s'expliquent pas par le diplôme ou les autres caractéristiques observées.", 'b_it_emp', '2013-2018', 'France', "L'écart d'emploi est réel ; les auteurs évoquent des difficultés « peut-être liées à de la discrimination à l'embauche ».", 'etabli', '24 %'),
  fait("Selon l'enquête Trajectoires et Origines 2, 2 % des descendants d'immigrés d'Algérie souhaitent s'installer dans le pays d'origine de leurs parents, contre 7 % des descendants d'immigrés du Portugal.", 'b_it_trans', '2019-2020', 'France métropolitaine', "L'attachement au pays d'origine n'est pas plus fort chez les descendants maghrébins que chez les descendants portugais.", 'etabli', '2 %'),
 ],
 court="Les Italiens aussi étaient jugés inassimilables : des ouvriers italiens ont été massacrés à Aigues-Mortes en 1893. Aujourd'hui, 95 % des descendants d'immigrés se sentent chez eux en France. Les descendants maghrébins progressent nettement sur leurs parents, mais déclarent trois fois plus de discriminations que ceux d'Europe du Sud : 35 % contre 12 %.",
 moyen="L'immigration italienne, aujourd'hui citée en modèle, a d'abord été rejetée : en 1893, des ouvriers italiens ont été massacrés à Aigues-Mortes, et la presse parlait de l'« Italien au couteau ». L'intégration se mesure sur des générations.\n\nChez les descendants d'immigrés maghrébins, la progression est nette : 20,0 % ont au plus le brevet, contre 36,5 % de leurs parents immigrés, et la part de couples mixtes passe de 17 % à 39 %. Des écarts persistent avec les descendants d'origine européenne, notamment pour le chômage et les couples mixtes. Mais ils déclarent aussi beaucoup plus de discriminations, 35 % pour les descendants d'origine algérienne contre 12 % pour l'Europe du Sud, et près d'un sur trois estime qu'on ne le voit pas comme Français, alors que 95 % des descendants d'immigrés se sentent chez eux en France.",
 detaille="L'idée d'une immigration européenne qui se serait intégrée sans peine oublie l'histoire. À la fin du XIXe siècle, les Italiens étaient décrits comme violents et inassimilables ; en 1893, à Aigues-Mortes, des ouvriers italiens ont été massacrés par une foule, et tous les accusés ont été acquittés. Leur intégration s'est faite sur plusieurs générations, et elle n'a pas été spontanée.\n\nLes données de l'enquête Trajectoires et Origines 2 (Insee-Ined, 2019-2020) permettent de comparer les descendants d'immigrés selon l'origine. Elles montrent une forte progression d'une génération à l'autre : la part des personnes ayant au plus le brevet passe de 36,5 % chez les immigrés du Maghreb à 20,0 % chez leurs descendants, et celle des couples avec une personne sans ascendance migratoire de 17 % à 39 %. Le sentiment d'appartenance est très fort : 95 % des descendants d'immigrés se sentent chez eux en France, davantage que les personnes sans ascendance migratoire (93 %). Et seuls 2 % des descendants d'origine algérienne souhaitent s'installer en Algérie, contre 7 % des descendants d'origine portugaise pour le Portugal.\n\nDes écarts réels persistent. Les couples mixtes sont deux fois moins fréquents que chez les descendants d'origine italienne, espagnole ou portugaise (78 %). Le chômage des hommes descendants d'immigrés du Maghreb atteignait 24 % entre 2013 et 2018, contre 9 % pour les descendants d'Europe du Sud. Mais une grande partie de cet écart, environ 10 points pour les hommes, ne s'explique ni par le diplôme ni par les autres caractéristiques observées. Et les descendants d'origine algérienne déclarent trois fois plus de discriminations (35 %) que ceux d'Europe du Sud (12 %) ; près d'un sur trois estime qu'on ne le voit pas comme Français.\n\nLe problème n'est donc pas un refus de s'intégrer, mais une intégration freinée par les discriminations. Comme pour les Italiens hier, c'est en luttant contre le rejet qu'on accélère l'égalité.",
 empathie="Beaucoup de familles ont vu des voisins italiens ou portugais devenir « comme tout le monde », et constatent des difficultés plus visibles dans certains quartiers. Ce ressenti mérite d'être pris au sérieux et confronté aux données.",
 legitimes=["Des écarts réels existent, notamment pour le chômage et les couples mixtes.", "L'intégration des Italiens et des Portugais est aujourd'hui largement réussie.", "Il est légitime de s'inquiéter de la concentration des difficultés dans certains quartiers."],
 contre=[
  ("Les Italiens étaient chrétiens, c'était plus facile.", "Ça ne les a pas protégés : en 1893, des ouvriers italiens ont été massacrés à Aigues-Mortes, et on les disait violents et inassimilables. L'intégration a pris des générations."),
  ("Le chômage des Maghrébins prouve qu'ils ne s'intègrent pas.", "À diplôme et caractéristiques égales, une grande partie de l'écart reste inexpliquée, et les descendants d'origine maghrébine déclarent trois fois plus de discriminations. Ce n'est pas un refus de s'intégrer."),
 ],
 questions=["Comment parlait-on des Italiens en France à la fin du XIXe siècle ?", "Si 95 % des descendants d'immigrés se sentent chez eux en France, pourquoi un sur trois parmi ceux d'origine maghrébine pense-t-il qu'on ne le voit pas comme Français ?"],
 limites=["Les données sur le chômage portent sur 2013-2018 ; celles de l'enquête TeO2 sur 2019-2020.", "Les chiffres du massacre d'Aigues-Mortes viennent d'une fiche de lecture universitaire du livre de Gérard Noiriel, pas du livre lui-même ; le bilan reste disputé.", "La statistique publique regroupe souvent Italie, Espagne et Portugal sous « Europe du Sud » ; les Portugais ne sont pas toujours isolés.", "Les discriminations sont déclarées par les personnes interrogées ; elles mesurent un vécu, pas des décisions de justice.", "Les pages de l'Ined présentant l'enquête TeO2 n'ont pas pu être ouvertes."],
 publics={'convaincus': "On disait exactement la même chose des Italiens : en 1893, on les a massacrés à Aigues-Mortes en les traitant de violents. Aujourd'hui, 95 % des descendants d'immigrés se sentent chez eux en France. Les enfants d'immigrés maghrébins font beaucoup mieux que leurs parents, mais déclarent trois fois plus de discriminations. Est-ce qu'ils refusent de s'intégrer, ou est-ce qu'on les en empêche ?",
  'indecis': "Les écarts sont réels : plus de chômage et moins de couples mixtes chez les descendants d'immigrés maghrébins. Mais ils progressent nettement par rapport à leurs parents et se sentent très majoritairement chez eux en France. Une grande partie de l'écart d'emploi ne s'explique pas par le diplôme, et ils déclarent 35 % de discriminations contre 12 % pour l'Europe du Sud."},
 a_actualiser='2027-06-30', raison="Nouvelle édition de l'Insee Références sur les immigrés et descendants d'immigrés et nouvelles exploitations de l'enquête TeO2.",
))


# ══ Lot C (18 novembre 2026, 20 h 13) : fessée et loi de 2019, instruction en famille, franchises médicales, masques et Covid, vaccins et autisme ══

# 1 ── « On ne peut plus donner une fessée à ses enfants, l'État s'en mêle. » ──────────────
C_FES_SENAT = ('c_fes_senat', src("Loi n° 2019-721 du 10 juillet 2019 relative à l'interdiction des violences éducatives ordinaires — dossier législatif", 'Sénat', '10 juillet 2019',
  'https://www.senat.fr/tableau-historique/ppl18-168.html',
  "Article 1er : l'article 371-1 du code civil est complété, après le deuxième alinéa, par la phrase : « L'autorité parentale s'exerce sans violences physiques ou psychologiques. » Le Gouvernement doit remettre au Parlement, avant le 1er septembre 2019, un rapport sur l'état des lieux des violences éducatives en France et sur les moyens de la politique de soutien à la parentalité et de formation des professionnels.",
  "Dossier législatif officiel du Sénat (texte définitif).", 'primaire'))
C_FES_PS2018 = ('c_fes_ps2018', src("L'Assemblée vote largement l'interdiction de la fessée", 'Public Sénat', '29 novembre 2018',
  'https://www.publicsenat.fr/actualites/politique/l-assemblee-vote-largement-l-interdiction-de-la-fessee-135995',
  "Adoption en première lecture par 51 voix pour, 1 contre et 3 abstentions. Le texte inscrit dans le code civil, dans l'article lu lors des mariages, que l'autorité parentale s'exerce sans violences physiques ou psychologiques. Il ne crée pas de nouvelles sanctions, qui existent déjà ; sa visée est « pédagogique » selon la rapporteure Maud Petit. Agnès Buzyn : « on n'éduque pas par la peur » ; la loi doit mettre fin à l'appréciation parfois souple du « droit de correction » par la jurisprudence. En commission, des élus de droite et d'extrême droite ont dénoncé une « ingérence » dans la vie des familles. La Suède a légiféré dès 1979 ; la France deviendrait le 55e État à interdire totalement les châtiments corporels selon une ONG basée à Londres.",
  "Chaîne parlementaire ; compte rendu du débat à l'Assemblée.", 'secondaire'))
C_FES_GI = ('c_fes_gi', src("Corporal punishment of children in France — country report", 'Global Initiative to End All Corporal Punishment of Children (ONG)', 'novembre 2024',
  'https://www.endcorporalpunishment.org/wp-content/uploads/country-reports/France.pdf',
  "La loi n° 2019-721 du 10 juillet 2019 interdit les châtiments corporels dans tous les cadres, y compris le domicile ; auparavant ils étaient licites au domicile au titre d'un « droit de correction » coutumier. Dans l'affaire APPROACH c. France (réclamation n° 92/2013), le Comité européen des droits sociaux du Conseil de l'Europe a jugé, par une décision adoptée le 12 septembre 2014 et publiée le 4 mars 2015, que la France violait l'article 17 de la Charte sociale européenne faute d'interdiction « sufficiently clear, binding and precise ». Le Comité des droits de l'enfant de l'ONU, dans ses observations finales du 4 décembre 2023, salue la loi de 2019 et recommande de la mettre en œuvre dans tous les cadres et de promouvoir une éducation non violente.",
  "Rapport d'une ONG spécialisée, qui cite les décisions du Conseil de l'Europe et de l'ONU.", 'secondaire'))
C_FES_UT = ('c_fes_ut', src("Risks of harm from spanking confirmed by analysis of five decades of research", 'Université du Texas à Austin (communiqué sur une méta-analyse publiée dans le Journal of Family Psychology)', '25 avril 2016',
  'https://news.utexas.edu/2016/04/25/risks-of-harm-from-spanking-confirmed-by-researchers',
  "Méta-analyse d'Elizabeth Gershoff (université du Texas) et Andrew Grogan-Kaylor (université du Michigan) portant sur plus de 160 000 enfants et cinq décennies de recherche. La fessée (coup donné main ouverte) est significativement associée à 13 des 17 effets étudiés, tous dans le sens défavorable (défiance, comportements antisociaux, agressivité, troubles de santé mentale, difficultés cognitives) ; aucune association avec une meilleure obéissance. Les adultes fessés enfants sont plus favorables aux punitions physiques. E. Gershoff : « spanking was associated with unintended detrimental outcomes ».",
  "Communiqué universitaire sur une méta-analyse publiée dans une revue à comité de lecture.", 'etude'))
C_FES_PS2026 = ('c_fes_ps2026', src("Fessées, gifles : les parents franchissent encore la ligne rouge, et surtout les pères", 'Public Sénat', '17 avril 2026',
  'https://www.publicsenat.fr/actualites/societe/fessees-gifles-les-parents-franchissent-encore-la-ligne-rouge-et-surtout-les-peres',
  "Troisième baromètre des violences éducatives ordinaires (Ifop pour la Fondation pour l'enfance), 1 005 parents d'enfants de 0 à 17 ans interrogés en ligne du 30 janvier au 9 février 2026. Sur l'année écoulée, 83 % des parents disent avoir eu recours à des violences verbales ou psychologiques et 37 % à des violences physiques. 40 % des pères contre 25 % des mères estiment que certains enfants ont besoin de punitions corporelles. 79 % des parents ayant subi des violences éducatives disent que leur propre éducation influence leur manière d'élever leurs enfants.",
  "Chaîne parlementaire, rendant compte d'un sondage commandé par une fondation.", 'secondaire'))
C_FES_BARO = ('c_fes_baro', src("Baromètre des violences éducatives ordinaires 2026 — synthèse", "Fondation pour l'enfance, Fondation de l'Université de Bretagne occidentale et Ifop", '2026',
  'https://www.fondation-enfance.org/wp-content/uploads/2026/04/121902-Synthese_VDef.pdf',
  "69 % des parents déclarent connaître la loi de 2019 sur les violences éducatives ordinaires ; 25 % pensent que la loi devrait permettre l'usage des punitions corporelles. 36 % jugent la fessée acceptable dans un but éducatif, 71 % estiment que c'est une mauvaise pratique disciplinaire et 68 % qu'elle est néfaste pour l'enfant. 84 % ont eu recours à au moins une violence éducative ordinaire sur l'année.",
  "Synthèse d'un sondage Ifop commandé par une fondation engagée contre les violences éducatives.", 'secondaire'))

FICHES.append(fiche(
 id='fessee-interdite-etat', affirmation="On ne peut plus donner une fessée à ses enfants, l'État s'en mêle.", volet='securite', sous_theme='Violences intrafamiliales',
 mots_cles=['loi anti fessee', 'interdiction de la fessee', 'fessee interdite', 'on peut plus donner une fessee', 'violences educatives ordinaires', 'l etat se mele de l education', 'droit de correction', 'gifle enfant loi', 'punition corporelle', 'loi du 10 juillet 2019'],
 verdict='plutot_exact', fiabilite='etabli',
 resume="Plutôt exact sur le droit, trompeur sur ce qu'on imagine derrière. Depuis la loi du 10 juillet 2019, le code civil précise que « l'autorité parentale s'exerce sans violences physiques ou psychologiques » : la fessée n'est donc plus permise. Mais la loi n'a créé aucune sanction pénale nouvelle ; elle a une visée « pédagogique ». La France a suivi la Suède (1979) et répondu à une condamnation du Conseil de l'Europe, et les recherches associent la fessée à des effets défavorables sans amélioration de l'obéissance.",
 contexte="L'expression « loi anti-fessée » circule depuis le vote de 2018-2019. Elle nourrit l'idée d'un État qui viendrait surveiller les familles et punir les parents, alors que beaucoup d'adultes ont eux-mêmes été élevés avec des fessées et ne s'en estiment pas abîmés.",
 explication="On distingue ce que dit exactement la loi (droit civil, sans sanction nouvelle), pourquoi elle a été votée (engagements européens et internationaux), ce que disent les recherches sur les effets des châtiments corporels et ce que font réellement les parents aujourd'hui.",
 sources=[C_FES_SENAT, C_FES_PS2018, C_FES_GI, C_FES_UT, C_FES_PS2026, C_FES_BARO],
 faits=[
  fait("La loi n° 2019-721 du 10 juillet 2019 a complété l'article 371-1 du code civil par la phrase : « L'autorité parentale s'exerce sans violences physiques ou psychologiques. »", 'c_fes_senat', 'depuis 2019', 'France', "La fessée n'est plus compatible avec la définition légale de l'autorité parentale : sur ce point, l'affirmation est exacte.", 'etabli'),
  fait("Selon Public Sénat, le texte ne crée pas de nouvelles sanctions, qui existaient déjà, et sa visée est « pédagogique » ; il a été adopté en première lecture à l'Assemblée par 51 voix pour et 1 contre.", 'c_fes_ps2018', '2018', 'France', "Aucun parent ne va en prison pour une fessée à cause de cette loi : elle fixe une norme et supprime l'excuse du « droit de correction », sans nouveau délit.", 'etabli', '51'),
  fait("Selon le rapport de la Global Initiative to End All Corporal Punishment of Children, le Comité européen des droits sociaux du Conseil de l'Europe avait jugé en 2014, dans une décision publiée le 4 mars 2015, que la France violait la Charte sociale européenne faute d'interdiction claire des châtiments corporels.", 'c_fes_gi', '2014-2015', 'France, Conseil de l’Europe', "La loi de 2019 répond à un engagement européen de la France, pas à une lubie gouvernementale.", 'etabli'),
  fait("Selon Public Sénat, la Suède a interdit les châtiments corporels dès 1979, et la France est devenue l'un des derniers pays d'Europe de l'Ouest à le faire, environ 55e État au monde selon une ONG.", 'c_fes_ps2018', '1979-2019', 'Monde', "La France n'est pas pionnière : elle rattrape un mouvement engagé depuis quarante ans.", 'etabli', '1979'),
  fait("Selon une méta-analyse d'Elizabeth Gershoff et Andrew Grogan-Kaylor portant sur plus de 160 000 enfants, la fessée est associée à 13 des 17 effets étudiés, tous défavorables (agressivité, comportements antisociaux, troubles de santé mentale), et à aucune amélioration de l'obéissance.", 'c_fes_ut', '1960-2016 (cinq décennies d’études)', 'principalement États-Unis', "La fessée n'apprend pas à obéir mieux, et elle va avec davantage de difficultés pour l'enfant.", 'etabli', '160 000'),
  fait("Selon le baromètre Ifop pour la Fondation pour l'enfance publié en 2026, 37 % des parents disent avoir eu recours à des violences physiques sur l'année écoulée, et 40 % des pères contre 25 % des mères estiment que certains enfants ont besoin de punitions corporelles.", 'c_fes_ps2026', '2026', 'France', "Sept ans après la loi, la pratique reste répandue : la loi n'a pas transformé les familles du jour au lendemain, ce qui montre aussi qu'elle ne fonctionne pas comme une machine à punir.", 'estimation', '37 %'),
  fait("Selon la synthèse du même baromètre, 69 % des parents déclarent connaître la loi de 2019, mais 36 % jugent encore la fessée acceptable dans un but éducatif et 25 % pensent que la loi devrait permettre les punitions corporelles.", 'c_fes_baro', '2026', 'France', "Une partie importante des parents reste attachée à la fessée : le débat existe et mérite mieux que des caricatures.", 'estimation', '69 %'),
  fait("Fait défavorable : la loi touche bien à l'éducation donnée dans les familles ; selon Public Sénat, des élus de droite et d'extrême droite y ont vu une « ingérence » dans la vie des familles, et les résultats de la méta-analyse de 2016 sont des associations statistiques, pas des expériences contrôlées.", 'c_fes_ps2018', '2018', 'France', "Il est exact que l'État fixe désormais une règle sur la manière d'éduquer, et la recherche mesure des liens plutôt que des causes démontrées une par une ; mais ces liens sont constants et aucune étude citée ne montre de bénéfice de la fessée.", 'etabli'),
 ],
 court="Oui, depuis 2019, le code civil dit que l'autorité parentale s'exerce « sans violences physiques ou psychologiques ». Mais la loi n'a créé aucune sanction nouvelle : elle pose une règle, comme la Suède l'a fait dès 1979. Et la fessée n'améliore pas l'obéissance, selon une méta-analyse sur plus de 160 000 enfants.",
 moyen="La loi du 10 juillet 2019 a ajouté une phrase au code civil : l'autorité parentale s'exerce sans violences physiques ou psychologiques. La fessée n'est donc plus permise, c'est vrai. Mais le texte ne crée aucun nouveau délit ; sa visée est « pédagogique », et il met fin à l'idée d'un « droit de correction » des parents. Il répond aussi à une condamnation de la France par le Comité européen des droits sociaux du Conseil de l'Europe.\n\nCe choix s'appuie sur la recherche : une méta-analyse portant sur plus de 160 000 enfants associe la fessée à davantage d'agressivité et de troubles, et à aucune amélioration de l'obéissance. Dans les faits, la pratique reste fréquente : en 2026, 37 % des parents disent avoir eu recours à des violences physiques dans l'année. Le débat est légitime, mais il porte sur la meilleure façon d'aider les parents, pas sur une police des familles.",
 detaille="Depuis la loi n° 2019-721 du 10 juillet 2019, l'article 371-1 du code civil, celui qu'on lit lors des mariages, précise : « L'autorité parentale s'exerce sans violences physiques ou psychologiques. » La fessée, la gifle ou les humiliations ne sont donc plus compatibles avec l'autorité parentale telle que la loi la définit. Sur ce point, l'affirmation est exacte.\n\nCe qu'elle sous-entend l'est beaucoup moins. La loi ne crée aucune sanction pénale nouvelle : les violences sur un enfant étaient déjà punissables, et le texte, selon sa rapporteure, a une visée « pédagogique ». Il supprime surtout l'excuse d'un « droit de correction » coutumier que certains juges admettaient encore. Il répond à des engagements internationaux : le Comité européen des droits sociaux du Conseil de l'Europe avait jugé en 2014 que la France violait la Charte sociale européenne faute d'interdiction claire, et le Comité des droits de l'enfant de l'ONU a salué la loi en 2023. La Suède avait franchi le pas dès 1979.\n\nLa recherche donne raison à ce choix. Une méta-analyse de 2016 portant sur plus de 160 000 enfants associe la fessée à 13 effets défavorables sur 17 étudiés, sans amélioration de l'obéissance. Il s'agit d'associations statistiques, mais elles vont toutes dans le même sens. En France, la pratique résiste : en 2026, 37 % des parents disent avoir eu recours à des violences physiques dans l'année, et 36 % jugent encore la fessée acceptable dans un but éducatif, alors que 69 % disent connaître la loi.\n\nL'État ne s'invite donc pas dans chaque foyer : il fixe un repère, comme il l'a fait pour d'autres violences autrefois tolérées dans la famille. La vraie question est celle des moyens donnés aux parents, souvent épuisés, pour éduquer autrement : soutien à la parentalité, protection maternelle et infantile, temps et conditions de vie.",
 empathie="Beaucoup de parents ont reçu des fessées enfants et aiment leurs propres parents ; ils peuvent vivre la loi comme un jugement sur leur famille. Il est possible de reconnaître cela tout en expliquant ce que l'on sait aujourd'hui.",
 legitimes=["Il est exact que la fessée n'est plus permise par le code civil depuis 2019.", "Éduquer des enfants est difficile, et les parents manquent souvent d'aide concrète plus que de règles.", "Les études mesurent des associations : on peut demander des preuves solides avant de juger les parents."],
 contre=[
  ("On va se retrouver au tribunal pour une fessée.", "La loi de 2019 n'a créé aucune sanction pénale nouvelle ; elle a une visée pédagogique et supprime seulement l'excuse du « droit de correction »."),
  ("J'en ai reçu et je ne m'en porte pas plus mal.", "Chacun peut le ressentir ainsi, mais sur plus de 160 000 enfants étudiés, la fessée n'améliore pas l'obéissance et va avec davantage de difficultés. Ce qui compte, c'est ce qui marche le mieux pour l'enfant."),
  ("C'est une idée de Bruxelles ou de bobos.", "C'est le Conseil de l'Europe, pas l'Union européenne, qui avait épinglé la France, et la Suède l'a fait dès 1979. Des pays très différents ont suivi."),
 ],
 questions=["Qu'est-ce qu'une fessée apprend à un enfant, d'après toi ?", "De quoi les parents auraient-ils le plus besoin pour éduquer sans violence : de règles, de temps, d'aide ?"],
 limites=["La méta-analyse de 2016 a été lue à travers le communiqué de l'université du Texas, pas dans son texte intégral ; elle porte surtout sur des études nord-américaines.", "Le baromètre de 2026 est un sondage en ligne commandé par une fondation engagée ; ses chiffres sont déclaratifs.", "Les décisions du Conseil de l'Europe et de l'ONU sont rapportées par une ONG spécialisée ; les textes originaux n'ont pas été ouverts.", "Le texte consolidé de l'article 371-1 sur Légifrance et la fiche de Vie publique n'ont pas été ouverts : la rédaction citée vient du dossier législatif du Sénat.", "Le chiffre de « 55e État » vient d'une ONG citée par Public Sénat en 2018."],
 publics={'convaincus': "Tu as raison sur un point : depuis 2019, la loi dit que l'autorité parentale s'exerce sans violences. Mais personne ne va en prison pour ça, la loi n'a créé aucune sanction nouvelle. Et sur plus de 160 000 enfants étudiés, la fessée ne rend pas plus obéissant : ce n'est pas l'État contre les parents, c'est ce qui marche ou pas.",
  'indecis': "La loi de 2019 interdit bien les violences éducatives, mais elle n'a pas créé de nouveau délit : elle fixe un repère, comme la Suède en 1979. Les recherches associent la fessée à plus d'agressivité et pas à plus d'obéissance. Si on hésite, la question utile est : de quelle aide les parents ont-ils besoin pour faire autrement ?"},
 a_actualiser='2028-06-30', raison="Prochaine édition du baromètre des violences éducatives ordinaires (tous les deux ans) et éventuelles évolutions législatives.",
))


# 2 ── « On nous interdit l'école à la maison. » ──────────────
C_IEF_CC = ('c_ief_cc', src("Décision n° 2021-823 DC du 13 août 2021 — communiqué de presse", 'Conseil constitutionnel', '13 août 2021',
  'https://www.conseil-constitutionnel.fr/actualites/communique/decision-n-2021-823-dc-du-13-aout-2021-communique-de-presse',
  "Les requérants reprochaient à l'article 49 de « méconnaître le principe fondamental reconnu par les lois de la République de liberté de l'enseignement » en remplaçant la déclaration par une autorisation préalable. Le Conseil relève que la loi du 28 mars 1882 « n'a fait de l'instruction en famille qu'une modalité de mise en œuvre de l'instruction obligatoire », qui n'est donc pas « une composante du principe fondamental » de liberté de l'enseignement. L'autorisation suppose de vérifier la « capacité » de la personne chargée d'instruire et un projet comportant « les éléments essentiels de l'enseignement et de la pédagogie ». Réserve : le pouvoir réglementaire doit fixer les modalités de délivrance de l'autorisation en excluant toute discrimination. L'article 49 n'est pas censuré.",
  "Communiqué officiel de la juridiction constitutionnelle.", 'primaire'))
C_IEF_CE = ('c_ief_ce', src("Décision n° 467550 du 13 décembre 2022 — analyse", "Conseil d'État", '13 décembre 2022',
  'https://www.conseil-etat.fr/fr/arianeweb/CE/analyse/2022-12-13/467550',
  "Les enfants soumis à l'obligation scolaire sont en principe instruits dans un établissement ou une école ; l'instruction en famille est une dérogation. Saisie d'une demande, l'administration compare, pour cet enfant, l'école et l'instruction en famille et retient « la forme d'instruction la plus conforme à son intérêt ». Pour le motif tiré d'une situation propre à l'enfant, elle vérifie que la demande « expose de manière étayée la situation propre à cet enfant », que le projet éducatif est adapté à ses capacités et à son rythme et que les personnes chargées de l'instruction peuvent lui faire acquérir le socle commun.",
  "Jurisprudence de la juridiction administrative suprême.", 'primaire'))
C_IEF_QE = ('c_ief_qe', src("Question écrite n° 11211 — réponse du ministère de l'Éducation nationale et de la Jeunesse", 'Assemblée nationale (Journal officiel)', '19 mars 2024',
  'https://www.assemblee-nationale.fr/dyn/16/questions/QANR5L16QE11211.pdf',
  "Pour l'année scolaire 2023-2024, au 1er décembre 2023 : 51 229 demandes d'instruction en famille instruites, dont 45 275 autorisées, soit 88,4 %. Pour le motif 4° (situation propre à l'enfant) : 6 169 demandes instruites, dont 4 041 autorisées, soit 65,5 %.",
  "Réponse ministérielle publiée au Journal officiel.", 'primaire'))
C_IEF_CDC = ('c_ief_cdc', src("École à la maison : la Cour des comptes pointe des failles", 'Handicap.fr, avec l’AFP, sur un rapport de la Cour des comptes du 25 juin 2025', '28 juin 2025',
  'https://informations.handicap.fr/a-ecole-a-la-maison-la-cour-des-comptes-pointe-des-failles-38185.php',
  "Depuis la loi du 24 août 2021, l'instruction en famille exige une autorisation préalable au lieu d'une simple déclaration, pour quatre motifs : état de santé ou handicap de l'enfant ; pratique intensive d'activités sportives ou artistiques ; itinérance de la famille ou éloignement des établissements ; situation propre à l'enfant motivant le projet éducatif. 30 644 enfants instruits en famille en 2024-2025 ; ils étaient 13 547 (6-16 ans) en 2007-2008 et 72 369 (3-16 ans) en 2021-2022, hausse liée notamment au Covid-19. 34 % des autorisations de 2024-2025 relèvent d'une situation propre à l'enfant. La Cour note une « plus grande sécurisation » mais des contrôles pédagogiques qui « ne sont pas tous effectués » et un contrôle municipal « peu effectif ».",
  "Dépêche reprenant un rapport de la Cour des comptes (rapport lui-même non ouvert).", 'secondaire'))
C_IEF_LCP = ('c_ief_lcp', src("Instruction en famille : dans un rapport, deux députés pointent la chute du nombre d'enfants", 'Maxence Kagni, LCP-Assemblée nationale', '7 octobre 2026',
  'https://lcp.fr/actualites/instruction-en-famille-dans-un-rapport-deux-deputes-pointent-la-chute-du-nombre-d',
  "Mission d'information de Josiane Corneloup (Droite républicaine) et Vincent Trébuchet (Union des droites pour la République). Enfants instruits en famille : 72 369 en 2021-2022, 55 747 en 2022-2023, près de 30 000 autorisations en 2025-2026, soit moins de 1 % des enfants de 3 à 16 ans. En 2021, Jean-Michel Blanquer évoquait un « phénomène de fuite de l'école » lié à l'islamisme radical, aux phénomènes sectaires et à la radicalisation ; selon les corapporteurs, aucune donnée objective n'a permis de documenter ce phénomène. Ils proposent un retour à un régime déclaratif, renforcé à partir de 6 ans.",
  "Chaîne parlementaire, rendant compte d'un rapport de députés de droite (position politique).", 'secondaire'))

FICHES.append(fiche(
 id='instruction-en-famille-interdite', affirmation="On nous interdit l'école à la maison.", volet='droits', sous_theme='Libertés publiques',
 mots_cles=['ecole a la maison interdite', 'instruction en famille', 'ief interdite', 'loi separatisme ecole a la maison', 'autorisation instruction en famille', 'liberte d enseignement', 'homeschooling france', 'refus ief', 'scolarisation obligatoire 3 ans', 'on nous interdit l ecole a la maison'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. L'école à la maison n'est pas interdite : depuis la loi du 24 août 2021, elle exige une autorisation pour l'un de quatre motifs, et en 2023-2024, 88,4 % des demandes ont été acceptées. Mais la liberté a réellement reculé : le nombre d'enfants instruits en famille est passé de 72 369 en 2021-2022 à 30 644 en 2024-2025, et la lutte contre le séparatisme, qui a justifié la réforme, a été peu documentée par des données.",
 contexte="La loi « confortant le respect des principes de la République », dite loi séparatisme, a supprimé le régime de simple déclaration. Des familles, souvent sans lien avec la religion, y ont vu une interdiction ; des responsables de droite demandent aujourd'hui un retour en arrière.",
 explication="On distingue ce que dit la loi et la jurisprudence, les chiffres d'autorisations et de refus, l'évolution du nombre d'enfants concernés et la justification politique avancée en 2021.",
 sources=[C_IEF_CC, C_IEF_CE, C_IEF_QE, C_IEF_CDC, C_IEF_LCP],
 faits=[
  fait("Selon la Cour des comptes, citée par l'AFP, l'instruction en famille exige depuis la loi du 24 août 2021 une autorisation préalable au lieu d'une simple déclaration, pour l'un de quatre motifs : santé ou handicap, activités sportives ou artistiques intensives, itinérance ou éloignement, situation propre à l'enfant.", 'c_ief_cdc', 'depuis 2022', 'France', "Ce n'est pas une interdiction mais un régime d'autorisation, qui restreint le libre choix des parents.", 'etabli'),
  fait("Le Conseil constitutionnel a jugé le 13 août 2021 que l'instruction en famille n'est pas « une composante du principe fondamental » de liberté de l'enseignement, et a validé l'autorisation préalable sous réserve qu'elle soit délivrée sans discrimination.", 'c_ief_cc', '2021', 'France', "La réforme est conforme à la Constitution : l'école à la maison est une modalité de l'instruction obligatoire, que la loi peut encadrer.", 'etabli'),
  fait("Selon la réponse du ministère de l'Éducation nationale publiée au Journal officiel, en 2023-2024, 45 275 des 51 229 demandes instruites ont été autorisées, soit 88,4 % ; pour le motif « situation propre à l'enfant », 4 041 sur 6 169, soit 65,5 %.", 'c_ief_qe', '2023-2024', 'France', "La grande majorité des demandes est acceptée ; le taux de refus est nettement plus élevé pour le motif « situation propre à l'enfant », celui des projets éducatifs choisis par les familles.", 'etabli', '88,4 %'),
  fait("Le Conseil d'État a jugé le 13 décembre 2022 que l'administration doit retenir « la forme d'instruction la plus conforme à son intérêt », sans exiger des parents qu'ils prouvent que l'école est impossible, à condition que la situation de l'enfant soit exposée de manière étayée.", 'c_ief_ce', '2022', 'France', "Le juge a fixé un cadre centré sur l'intérêt de l'enfant, qui permet de contester les refus mal motivés.", 'etabli'),
  fait("Selon la Cour des comptes, citée par l'AFP, 30 644 enfants étaient instruits en famille en 2024-2025, contre 72 369 en 2021-2022 et 13 547 en 2007-2008 ; la hausse antérieure était liée notamment à la pandémie de Covid-19.", 'c_ief_cdc', '2007-2025', 'France', "La pratique reste possible mais a été plus que divisée par deux depuis son pic.", 'etabli', '30 644'),
  fait("Selon la Cour des comptes, citée par l'AFP, les contrôles pédagogiques des enfants instruits en famille « ne sont pas tous effectués » et le contrôle par les mairies reste « peu effectif ».", 'c_ief_cdc', '2025', 'France', "Le vrai point faible est le suivi des enfants, qui dépend de moyens publics pour contrôler et accompagner.", 'etabli'),
  fait("Fait défavorable : selon un rapport de deux députés de droite rendu public le 7 octobre 2026 et rapporté par LCP, aucune donnée objective n'a permis de documenter le « phénomène de fuite de l'école » lié à la radicalisation invoqué en 2021, et les autorisations sont tombées à près de 30 000 en 2025-2026.", 'c_ief_lcp', '2021-2026', 'France', "La restriction est réelle et sa justification par le séparatisme a été peu étayée : les familles qui se sentent visées ont des raisons de le penser.", 'interpretation', '30 000'),
  fait("Fait défavorable : selon la même réponse ministérielle, environ un tiers des demandes fondées sur une situation propre à l'enfant n'ont pas été autorisées en 2023-2024 (65,5 % d'autorisations).", 'c_ief_qe', '2023-2024', 'France', "Pour les familles dont le projet repose sur la situation propre de leur enfant, le risque de refus est important.", 'etabli', '65,5 %'),
 ],
 court="Non, l'école à la maison n'est pas interdite : depuis 2021 il faut une autorisation, et 88,4 % des demandes ont été acceptées en 2023-2024. Mais c'est une vraie restriction : on est passé de 72 369 enfants en 2021-2022 à 30 644 en 2024-2025, et l'argument du séparatisme a été peu étayé.",
 moyen="La loi du 24 août 2021 a remplacé la simple déclaration par une autorisation, accordée pour quatre motifs : santé ou handicap, activités intensives, itinérance, ou situation propre à l'enfant. Le Conseil constitutionnel l'a validée, et le Conseil d'État exige que l'administration choisisse la forme d'instruction la plus conforme à l'intérêt de l'enfant. En 2023-2024, 88,4 % des demandes ont été acceptées : parler d'interdiction est faux.\n\nLa liberté des familles a pourtant reculé. Le nombre d'enfants instruits en famille est tombé à 30 644 en 2024-2025, et environ un tiers des demandes fondées sur la situation propre à l'enfant ne sont pas autorisées. La réforme avait été justifiée par la lutte contre la radicalisation, mais un rapport parlementaire de 2026 estime qu'aucune donnée n'a documenté ce phénomène. Le débat sérieux porte sur l'équilibre entre liberté des familles, droit de l'enfant à l'instruction et moyens de contrôle.",
 detaille="Avant la réforme, une simple déclaration suffisait pour instruire son enfant en famille. La loi du 24 août 2021 « confortant le respect des principes de la République » a instauré une autorisation préalable, accordée pour quatre motifs : l'état de santé ou le handicap de l'enfant, la pratique intensive d'une activité sportive ou artistique, l'itinérance ou l'éloignement d'un établissement, ou une situation propre à l'enfant motivant un projet éducatif. Le Conseil constitutionnel a jugé le 13 août 2021 que l'instruction en famille n'est qu'une modalité de l'instruction obligatoire, pas une composante de la liberté de l'enseignement, et a validé le dispositif sous réserve qu'il ne soit pas discriminatoire.\n\nDans les faits, l'école à la maison existe toujours. En 2023-2024, 45 275 demandes sur 51 229 ont été autorisées, soit 88,4 %. Le Conseil d'État a précisé que les parents n'ont pas à prouver que l'école est impossible : l'administration doit retenir la forme d'instruction la plus conforme à l'intérêt de l'enfant, au vu d'une situation étayée et d'un projet pédagogique sérieux.\n\nIl serait malhonnête de nier la restriction. Le nombre d'enfants instruits en famille est passé de 72 369 en 2021-2022, pic gonflé par le Covid, à 30 644 en 2024-2025. Pour le motif « situation propre à l'enfant », seules 65,5 % des demandes étaient acceptées en 2023-2024. Et l'argument central de 2021, une « fuite de l'école » liée à la radicalisation, n'a pas été documenté par des données selon un rapport parlementaire de 2026, rédigé il est vrai par des députés de droite hostiles à la réforme.\n\nUne position de gauche peut tenir ensemble deux exigences : défendre l'école publique comme lieu commun d'émancipation et d'égalité, et refuser qu'une liberté soit restreinte au nom d'une menace mal mesurée. La Cour des comptes rappelle que le vrai problème est ailleurs : les contrôles pédagogiques ne sont pas tous effectués. Garantir le droit de chaque enfant à l'instruction suppose d'abord des moyens pour suivre et accompagner, plutôt que des soupçons globaux.",
 empathie="Pour des parents qui ont construit un projet éducatif réfléchi, recevoir un refus ou se sentir soupçonnés de séparatisme est blessant. Leur colère se comprend, même si le mot « interdiction » ne correspond pas à la réalité.",
 legitimes=["Le passage de la déclaration à l'autorisation est une restriction réelle d'une liberté auparavant large.", "La justification par la lutte contre la radicalisation a été peu étayée par des données.", "Le taux de refus est élevé pour les projets fondés sur la situation propre à l'enfant, et les contrôles restent inégaux."],
 contre=[
  ("C'est interdit, point.", "En 2023-2024, 88,4 % des demandes ont été acceptées, et environ 30 000 enfants sont encore instruits en famille. C'est un régime d'autorisation, contestable, mais pas une interdiction."),
  ("La Constitution protège la liberté d'enseignement.", "Le Conseil constitutionnel a jugé en 2021 que l'instruction en famille n'en fait pas partie : c'est une modalité de l'instruction obligatoire que la loi peut encadrer."),
 ],
 questions=["Qu'est-ce qui garantit le mieux le droit de chaque enfant à apprendre : la liberté des parents, l'école commune, ou des contrôles bien faits ?", "Si l'argument du séparatisme était peu documenté, quelle règle te semblerait juste ?"],
 limites=["Le rapport de la Cour des comptes n'a pas été ouvert directement : il est connu par une dépêche AFP reprise par Handicap.fr.", "Les chiffres de 2023-2024 incluent la fin de la période transitoire où les familles déjà en instruction en famille bénéficiaient d'autorisations facilitées ; les taux peuvent avoir évolué depuis.", "Le rapport parlementaire de 2026 est rapporté par LCP et émane de députés de droite et d'extrême droite opposés à la réforme ; il est cité pour ce qu'il reconnaît, pas comme une autorité.", "La fiche de Vie publique sur le bilan de la réforme n'a pas pu être ouverte (accès bloqué)."],
 publics={'convaincus': "L'école à la maison n'est pas interdite : en 2023-2024, 88,4 % des demandes ont été acceptées. Tu as raison de dire que c'est plus dur qu'avant et que l'argument du séparatisme était mal étayé. Mais crier à l'interdiction empêche de discuter du vrai sujet : des règles justes et des contrôles bien faits pour chaque enfant.",
  'indecis': "Depuis 2021, il faut une autorisation pour l'un de quatre motifs, et le nombre d'enfants instruits en famille a été plus que divisé par deux. La grande majorité des demandes reste acceptée, mais les demandes fondées sur la situation propre à l'enfant sont plus souvent refusées. En cas de refus, le juge exige que l'administration regarde l'intérêt réel de l'enfant."},
 a_actualiser='2027-09-30', raison="Chiffres de la rentrée 2026-2027 et suites éventuelles du rapport parlementaire de 2026.",
))


# 3 ── « Les franchises médicales responsabilisent les patients, la santé est trop gratuite. » ──────────────
C_FRA_VIDAL = ('c_fra_vidal', src("Franchise médicale à 1 euro sur les médicaments : entrée en vigueur le 31 mars 2024", 'Vidal', '2024',
  'https://www.vidal.fr/actualites/30739-franchise-medicale-a-1-euro-sur-les-medicaments-entree-en-vigueur-le-31-mars-2024.html',
  "Décret n° 2024-114 du 16 février 2024, applicable au 31 mars 2024 : franchise de 0,50 € à 1 € par boîte de médicament et par acte paramédical, de 2 € à 4 € par transport sanitaire ; plafonds journaliers doublés. Plafond annuel de 50 € par an et par personne inchangé. Exonérations : moins de 18 ans, femmes enceintes bénéficiaires de l'assurance maternité, bénéficiaires de la complémentaire santé solidaire.",
  "Base d'information médicale professionnelle.", 'secondaire'))
C_FRA_SP = ('c_fra_sp', src("Frais médicaux : les plafonds des franchises et participations forfaitaires augmentent au 1er octobre 2026", 'Service-Public.fr (Direction de l’information légale et administrative)', '16 septembre 2026',
  'https://www.service-public.gouv.fr/particuliers/actualites/A17166?lang=fr',
  "Décret n° 2026-858 du 11 septembre 2026 : plafond annuel des franchises de 50 € à 70 €, des participations forfaitaires de 50 € à 70 €, soit 140 € cumulés au lieu de 100 €, à partir du 1er octobre 2026. Franchise : 1 € par boîte et par acte paramédical, 4 € par transport ; participation forfaitaire : 2 € par consultation ou acte de biologie. Exonérations : moins de 18 ans, complémentaire santé solidaire, femmes enceintes à partir du 6e mois. Revalorisation annuelle selon l'inflation à partir du 1er janvier 2028.",
  "Site officiel de l'administration française.", 'primaire'))
C_FRA_LCP = ('c_fra_lcp', src("Franchises médicales : ce qui va changer après les annonces du gouvernement", 'LCP-Assemblée nationale', '24 juillet 2026',
  'https://lcp.fr/index%2ephp/actualites/franchises-medicales-ce-qui-va-changer-apres-les-annonces-du-gouvernement-439936',
  "La ministre de la Santé Stéphanie Rist annonce un passage des plafonds de 50 à 100 € chacun (200 € au total) ; selon Les Echos, confirmé par Matignon, 750 millions d'euros par an attendus. Selon la Cour des comptes, les franchises et participations ont concerné 48 millions de personnes et rapporté 2,5 milliards d'euros en 2025. France Assos Santé dénonce une « erreur monumentale » ; la Mutualité française estime que la mesure pèsera surtout sur les personnes âgées et malades chroniques.",
  "Chaîne parlementaire.", 'secondaire'))
C_FRA_DREES = ('c_fra_drees', src("Les dépenses de santé en 2024 — Résultats des comptes de la santé, édition 2025", 'DREES (ministère de la Santé)', '30 septembre 2025',
  'https://drees.solidarites-sante.gouv.fr/publications-communique-de-presse-infographie-documents-de-reference/250930-Panorama-depenses-de-sante',
  "Consommation de soins et de biens médicaux de 255 milliards d'euros en 2024, financée à 79,4 % par la Sécurité sociale et l'État et à 12,8 % par les organismes complémentaires. Reste à charge des ménages : 7,8 % (en hausse de 0,1 point), soit 292 euros par habitant (276 en 2023). Au sens international, 10,2 % de la dépense courante, contre 14,8 % en moyenne dans l'Union européenne : la France est parmi les pays où il est le plus faible, juste derrière le Luxembourg et la Croatie. Le doublement des franchises et participations forfaitaires augmente la contribution des ménages.",
  "Service statistique public du ministère de la Santé.", 'primaire'))
C_FRA_RAND = ('c_fra_rand', src("The Health Insurance Experiment: A Classic RAND Study Speaks to the Current Health Care Reform Debate", 'RAND Corporation', '6 décembre 2006',
  'https://www.rand.org/pubs/research_briefs/RB9174.html',
  "Expérience menée de 1971 à 1982 auprès de 2 750 familles (plus de 7 700 personnes) aux États-Unis. Avec une participation financière, une à deux consultations de moins par an et 20 % d'hospitalisations en moins ; dépenses réduites de 20 % à 30 % selon le taux. Le ticket modérateur a réduit les soins efficaces comme les soins moins efficaces, à peu près dans les mêmes proportions pour les hospitalisations et les médicaments. « Cost sharing in general had no adverse effects on participant health », sauf pour les plus pauvres et les plus malades (environ 6 % de l'échantillon) : chez les hypertendus pauvres, la gratuité réduisait davantage la tension, soit une baisse de mortalité projetée d'environ 10 %.",
  "Synthèse officielle d'une expérience randomisée de référence.", 'etude'))
C_FRA_IRDES = ('c_fra_irdes', src("Les franchises ont-elles modifié les comportements d'achats de médicaments ?", 'IRDES, Questions d’économie de la santé n° 158 (B. Kambia-Chopin, M. Perronnin)', 'octobre 2010',
  'https://www.IRDES.fr/Publications/2010/Qes158.pdf',
  "Enquête santé protection sociale 2008 : 4 985 personnes ayant eu une prescription. 12 % déclarent avoir modifié leurs achats de médicaments à cause des franchises ; 14,3 % parmi les revenus inférieurs à 870 € par unité de consommation, contre 8,4 % au-delà de 1 997 €. Toutes choses égales par ailleurs, la probabilité est presque doublée pour les plus modestes et plus élevée en cas de mauvais état de santé ou de maladie chronique. 64 % de ceux qui ont modifié leurs achats n'ont acheté qu'une partie des médicaments prescrits.",
  "Institut public de recherche en économie de la santé.", 'etude'))
C_FRA_PS = ('c_fra_ps', src("« Le gouvernement n'a pas tranché ! » : la piste d'une hausse des franchises médicales enflamme le Sénat", 'Public Sénat', '16 novembre 2023',
  'https://www.publicsenat.fr/actualites/sante/le-gouvernement-na-pas-tranche-la-piste-dune-hausse-des-franchises-medicales-enflamme-le-senat',
  "Le doublement des franchises, envisagé après une hausse de 7,7 % de la consommation de médicaments en 2022, doit rapporter 800 millions d'euros ; il figure parmi les mesures de « responsabilisation des assurés ». Hausse moyenne d'environ 17 euros par an par patient. Le ministre Aurélien Rousseau dit redouter une mesure perçue comme une ponction sans effet sur la consommation de médicaments.",
  "Chaîne parlementaire.", 'secondaire'))
C_FRA_CAD = ('c_fra_cad', src("Franchises médicales à 140 euros cumulés : la hausse se concentre sur les plus gros consommateurs de soins", 'Caducee.net', '14 septembre 2026',
  'https://www.caducee.net/actualite-medicale/16965/franchises-medicales-a-140-euros-cumules-la-hausse-se-concentre-sur-les-plus-gros-consommateurs-de-soins.html',
  "Selon la Cour des comptes (rapport « La Sécurité sociale 2026 », mai 2026), les assurés en affection de longue durée paient en moyenne 78 € par an de franchises et participations, contre 41 € pour les autres ; la Cour ne démontre pas encore leur effet de responsabilisation. Environ 18 millions de personnes sont exonérées. Le projet initial à 200 € a été abandonné.",
  "Site d'information médicale, résumant un rapport de la Cour des comptes (non ouvert).", 'secondaire'))

FICHES.append(fiche(
 id='franchises-medicales-responsabiliser', affirmation="Les franchises médicales responsabilisent les patients, la santé est trop gratuite.", volet='services', sous_theme='Assurance maladie',
 mots_cles=['franchises medicales', 'franchise medicament 1 euro', 'responsabiliser les patients', 'la sante est trop gratuite', 'doublement des franchises', 'plafond franchises 140 euros', 'participation forfaitaire', 'reste a charge', 'renoncement aux soins', 'ticket moderateur'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Il est vrai que les Français paient peu de leur poche : 292 euros par habitant en 2024, un des restes à charge les plus faibles d'Europe. Mais les franchises, doublées en 2024 et dont le plafond est passé à 140 euros en octobre 2026, ne trient pas les soins utiles des soins inutiles : l'expérience de référence de la RAND montre que le ticket modérateur réduit les deux, et qu'il nuit aux plus pauvres et aux plus malades. En France, les malades chroniques paient presque deux fois plus que les autres.",
 contexte="Les franchises existent depuis 2008. Elles ont été doublées en 2024, puis leurs plafonds relevés en 2026, au nom de la « responsabilisation » et du déficit de la Sécurité sociale. L'idée d'une santé « trop gratuite » accompagne souvent ces décisions.",
 explication="On regarde ce que coûtent réellement les franchises, ce que paient les ménages en France par rapport à leurs voisins, et ce que disent les études sur l'effet d'une participation financière sur les soins et la santé.",
 sources=[C_FRA_VIDAL, C_FRA_SP, C_FRA_LCP, C_FRA_DREES, C_FRA_RAND, C_FRA_IRDES, C_FRA_PS, C_FRA_CAD],
 faits=[
  fait("Selon Vidal, le décret du 16 février 2024 a doublé les franchises au 31 mars 2024 : de 0,50 € à 1 € par boîte de médicament et par acte paramédical, de 2 € à 4 € par transport sanitaire.", 'c_fra_vidal', '2024', 'France', "Le montant payé à chaque soin a doublé en une fois.", 'etabli', '1 €'),
  fait("Selon Service-Public.fr, le décret n° 2026-858 a relevé au 1er octobre 2026 les plafonds annuels des franchises et des participations forfaitaires de 50 € à 70 € chacun, soit 140 € cumulés ; les moins de 18 ans, les bénéficiaires de la complémentaire santé solidaire et les femmes enceintes en sont exonérés.", 'c_fra_sp', '2026', 'France', "Ceux qui atteignent les plafonds, c'est-à-dire ceux qui se soignent le plus, paient davantage.", 'etabli', '140 €'),
  fait("Selon la Cour des comptes, citée par LCP, les franchises et participations forfaitaires ont concerné 48 millions de personnes et rapporté 2,5 milliards d'euros en 2025.", 'c_fra_lcp', '2025', 'France', "C'est d'abord une recette pour l'Assurance maladie, prélevée sur les malades.", 'etabli', '2,5 milliards d’euros'),
  fait("Selon la RAND Corporation, dans son expérience randomisée menée de 1971 à 1982 sur plus de 7 700 personnes, la participation financière a réduit les soins efficaces comme les soins moins efficaces, à peu près dans les mêmes proportions pour les hospitalisations et les médicaments.", 'c_fra_rand', '1971-1982', 'États-Unis', "Le patient ne sait pas trier à l'avance un soin utile d'un soin inutile : un frein financier réduit les deux.", 'etabli'),
  fait("Selon la RAND Corporation, dans la même expérience, les plus pauvres et les plus malades, environ 6 % de l'échantillon, étaient pénalisés : chez les hypertendus pauvres, la gratuité réduisait davantage la tension, soit une baisse de mortalité projetée d'environ 10 %.", 'c_fra_rand', '1971-1982', 'États-Unis', "Le coût sanitaire du ticket modérateur retombe sur ceux qui ont le plus besoin de soins.", 'etabli', '10 %'),
  fait("Selon l'IRDES, après la création des franchises en 2008, 12 % des personnes ayant eu une prescription déclaraient avoir modifié leurs achats de médicaments, 14,3 % parmi les plus modestes contre 8,4 % parmi les plus aisés ; 64 % d'entre elles n'avaient acheté qu'une partie des médicaments prescrits.", 'c_fra_irdes', '2008', 'France', "L'effet « responsabilisant » se traduit surtout par des ordonnances incomplètes chez les ménages modestes.", 'etabli', '12 %'),
  fait("Fait défavorable : selon la DREES, le reste à charge des ménages ne représentait en 2024 que 7,8 % de la consommation de soins, soit 292 euros par habitant ; au sens international, 10,2 % contre 14,8 % en moyenne dans l'Union européenne, un des plus faibles d'Europe.", 'c_fra_drees', '2024', 'France et Union européenne', "La santé est effectivement très socialisée en France, et c'est un choix collectif à défendre ; mais la moyenne cache les malades chroniques et ceux qui renoncent.", 'etabli', '292 euros'),
  fait("Fait défavorable : selon la RAND Corporation, dans son expérience, la participation financière n'a en général pas eu d'effet néfaste sur la santé du participant moyen, tout en réduisant les dépenses de 20 % à 30 %.", 'c_fra_rand', '1971-1982', 'États-Unis', "Les partisans du ticket modérateur s'appuient sur ce résultat ; il est ancien, américain, et ne vaut pas pour les plus pauvres et les plus malades.", 'etabli', '20 %'),
 ],
 court="Les Français paient peu de leur poche, 292 euros par habitant en 2024. Mais les franchises, plafonnées à 140 euros depuis octobre 2026, ne responsabilisent pas : l'expérience de référence de la RAND montre qu'un frein financier réduit autant les soins utiles que les inutiles, et pénalise les plus pauvres et les plus malades.",
 moyen="La France a un des restes à charge les plus faibles d'Europe : 292 euros par habitant en 2024, selon la DREES. Les franchises ont pourtant été doublées en 2024, puis leurs plafonds portés à 140 euros par an en octobre 2026. Elles ont rapporté 2,5 milliards d'euros en 2025, prélevés sur 48 millions de personnes.\n\nLe problème est qu'elles ne trient rien. Dans l'expérience randomisée de la RAND, la référence mondiale, le ticket modérateur réduisait autant les soins efficaces que les autres, et nuisait aux plus pauvres et aux plus malades. En France, après 2008, les ménages modestes ont été presque deux fois plus nombreux à modifier leurs achats de médicaments. Et les malades chroniques paient en moyenne 78 euros par an, contre 41 pour les autres.",
 detaille="Les franchises médicales sont des sommes laissées à la charge du patient, non remboursées ni par la Sécurité sociale ni par les complémentaires. Depuis mars 2024, elles s'élèvent à 1 euro par boîte de médicament ou par acte paramédical et 4 euros par transport sanitaire, auxquels s'ajoute une participation de 2 euros par consultation. Le décret du 11 septembre 2026 a porté les plafonds annuels à 70 euros chacun, soit 140 euros cumulés, avec une indexation sur l'inflation à partir de 2028. Selon la Cour des comptes, ces prélèvements ont touché 48 millions de personnes et rapporté 2,5 milliards d'euros en 2025.\n\nIl est vrai que la santé est très socialisée en France. Selon la DREES, les ménages ne paient directement que 7,8 % de la consommation de soins, soit 292 euros par habitant en 2024 ; au sens international, la France est parmi les pays européens où le reste à charge est le plus faible. Mais une moyenne cache des écarts : les malades en affection de longue durée paient en moyenne 78 euros par an de franchises et participations, contre 41 euros pour les autres.\n\nL'idée de « responsabiliser » suppose que le patient renonce d'abord aux soins inutiles. L'expérience randomisée de la RAND, menée de 1971 à 1982 sur plus de 7 700 personnes, montre l'inverse : la participation financière réduit à peu près autant les soins efficaces que les soins moins efficaces. Elle n'a pas nui à la santé du participant moyen, mais elle a pénalisé les plus pauvres et les plus malades, par exemple les hypertendus. En France, après la création des franchises, l'IRDES a mesuré que 14,3 % des plus modestes modifiaient leurs achats de médicaments, contre 8,4 % des plus aisés, souvent en n'achetant qu'une partie de l'ordonnance.\n\nCe sont les médecins qui prescrivent, pas les patients. Pour limiter les dépenses inutiles, il existe d'autres leviers : la régulation des prix des médicaments, la prévention, les pratiques de prescription. Taxer la maladie revient à faire payer davantage ceux qui ont le moins choisi d'être soignés.",
 empathie="Le déficit de la Sécurité sociale inquiète, et chacun a déjà vu une armoire à pharmacie pleine de boîtes inutilisées. Vouloir éviter le gaspillage est légitime ; la question est de savoir qui doit payer et si cela marche.",
 legitimes=["Le reste à charge en France est réellement l'un des plus faibles d'Europe.", "Le gaspillage de médicaments et les soins inutiles existent et coûtent cher.", "L'expérience de la RAND n'a pas trouvé d'effet néfaste sur la santé du participant moyen."],
 contre=[
  ("Un euro la boîte, ce n'est rien.", "Pour un malade chronique, cela fait en moyenne 78 euros par an, et le plafond est passé à 140 euros. Après 2008, les plus modestes étaient presque deux fois plus nombreux à acheter moins de médicaments."),
  ("Sans ticket, les gens abusent.", "L'expérience de la RAND montre que le frein financier réduit autant les soins utiles que les inutiles : le patient ne sait pas faire le tri, c'est le médecin qui prescrit."),
  ("Il faut bien boucher le trou de la Sécu.", "Les franchises ont rapporté 2,5 milliards d'euros en 2025, pris sur les malades. On peut aussi agir sur les recettes, les prix des médicaments ou la prévention."),
 ],
 questions=["Si le patient ne peut pas savoir à l'avance quel soin est utile, comment pourrait-il se « responsabiliser » ?", "Est-il juste que les malades chroniques paient presque deux fois plus que les autres ?"],
 limites=["L'expérience de la RAND date des années 1970 et porte sur les États-Unis ; elle a été lue à travers la synthèse officielle de 2006.", "L'étude de l'IRDES porte sur 2008 et mesure des modifications d'achats déclarées, pas un renoncement aux soins au sens strict.", "Le rapport de la Cour des comptes de 2026 n'a pas été ouvert : il est connu par LCP et Caducee.net.", "Les études de la DREES sur le renoncement aux soins n'ont pas pu être ouvertes (accès bloqué).", "L'article de Vidal n'indique pas le rendement du doublement de 2024 ; le chiffre de 800 millions d'euros est une estimation citée en 2023 par Public Sénat."],
 publics={'convaincus': "C'est vrai, en France on paie peu de sa poche, 292 euros par an en moyenne. Mais regarde qui paie les franchises : les malades chroniques, 78 euros par an en moyenne, contre 41 pour les autres. Et l'étude de référence montre qu'un ticket fait renoncer autant aux soins utiles qu'aux inutiles : c'est une taxe sur la maladie, pas une leçon de responsabilité.",
  'indecis': "Vouloir éviter le gaspillage est légitime, et le reste à charge français est faible. Mais les franchises ne trient pas les soins : elles freinent surtout les plus modestes et les plus malades. Depuis octobre 2026, le plafond est de 140 euros par an, et les moins de 18 ans, les femmes enceintes et les bénéficiaires de la complémentaire santé solidaire restent exonérés."},
 a_actualiser='2027-10-31', raison="Rendement du relèvement des plafonds de 2026, prochain rapport de la Cour des comptes et mesures du budget de la Sécurité sociale pour 2027.",
))


# 4 ── « Les masques ne servaient à rien contre le Covid. » ──────────────
C_MAS_COCH = ('c_mas_coch', src("Statement on 'Physical interventions to interrupt or reduce the spread of respiratory viruses' review", 'Cochrane (Karla Soares-Weiser, rédactrice en chef de la Cochrane Library)', '10 mars 2023 (mis à jour en juin 2024)',
  'https://www.cochrane.org/news/statement-physical-interventions-interrupt-or-reduce-spread-respiratory-viruses-review',
  "L'interprétation selon laquelle la revue montrerait que « masks don't work » est « an inaccurate and misleading interpretation ». La revue examinait si les interventions de promotion du masque ralentissent la propagation : « the results were inconclusive ». Elle « is not able to address the question of whether mask-wearing itself reduces people's risk ». « The high risk of bias in the trials » empêche des conclusions fermes. Cochrane regrette que la formulation du résumé (« We are uncertain whether wearing masks or N95/P2 respirators helps to slow the spread ») ait été « open to misinterpretation ».",
  "Déclaration officielle de l'éditeur de la revue systématique.", 'primaire'))
C_MAS_BGD = ('c_mas_bgd', src("The Impact of Community Masking on COVID-19: A Cluster Randomized Trial in Bangladesh", 'Cowles Foundation, université Yale (J. Abaluck, L. H. Kwong, M. Mobarak et al.), document de travail CFDP 2284R', 'avril 2021, révisé en mai 2022',
  'https://cowles.yale.edu/research/cfdp-2284r-impact-community-masking-covid-19-cluster-randomized-trial-bangladesh',
  "Essai randomisé par grappes dans 600 villages, 342 126 adultes. Le port correct du masque passe de 13,3 % dans les villages témoins à 42,3 % dans les villages d'intervention. Réduction de la séroprévalence symptomatique de 9,3 % au total (aPR = 0,91 [0,82 ; 1,00]) ; de 11,2 % dans les villages à masques chirurgicaux (aPR = 0,89) et de 34,7 % chez les 60 ans et plus de ces villages (aPR = 0,65).",
  "Résumé d'un essai randomisé à grande échelle (document de travail universitaire).", 'etude'))
C_MAS_DAN = ('c_mas_dan', src("Denmark trial measures effectiveness of adding a mask recommendation to other public health measures (DANMASK-19)", 'American College of Physicians (éditeur des Annals of Internal Medicine)', '18 novembre 2020',
  'https://www.acponline.org/acp-newsroom/denmark-trial-measures-effectiveness-of-adding-a-mask-recommendation-to-other-public-health-measures',
  "6 024 adultes randomisés ; après un mois, 1,8 % d'infections dans le groupe masque contre 2,1 % dans le groupe témoin. Les données écartent un effet protecteur personnel important, appuient faiblement une protection plus modeste, mais « cannot definitively exclude no effect ». L'essai ne mesurait pas la protection des autres (contrôle à la source) ; selon les éditeurs, il ne contredit pas la recommandation d'un port généralisé et suggère que le bénéfice personnel est plus faible que le bénéfice pour l'entourage.",
  "Communiqué de l'éditeur sur un essai randomisé publié dans une revue à comité de lecture.", 'etude'))
C_MAS_OMS = ('c_mas_oms', src("Coronavirus disease (COVID-19): When and how to use masks", 'Organisation mondiale de la santé', 'décembre 2021 (dernière mise à jour)',
  'https://www.who.int/emergencies/diseases/novel-coronavirus-2019/advice-for-public/when-and-how-to-use-masks',
  "« Masks should be used as part of a comprehensive strategy of measures to suppress transmission and save lives » ; « the use of a mask alone is not sufficient to provide an adequate level of protection against COVID-19 ».",
  "Recommandations officielles de l'OMS.", 'primaire'))
C_MAS_SPF = ('c_mas_spf', src("COVID-19 : état des connaissances sur la généralisation de l'utilisation des masques dans l'espace public", 'Santé publique France', '5 mai 2020',
  'https://www.santepubliquefrance.fr/les-actualites/2020/covid-19-etat-des-connaissances-sur-la-generalisation-de-l-utilisation-des-masques-dans-l-espace-public',
  "« Des études montrent une réduction modérée cependant non significative des infections respiratoires » avec le port du masque en population générale. L'efficacité des masques alternatifs en tissu « n'est pas acquise ». En cas de quantité limitée, les masques chirurgicaux doivent être réservés en priorité aux soins. Le masque doit être associé aux gestes barrières et à la distanciation.",
  "Synthèse rapide de l'agence nationale de santé publique.", 'primaire'))
C_MAS_OPECST = ('c_mas_opecst', src("Épidémie de COVID-19 — Les enjeux d'une généralisation du port des masques (note scientifique)", "Office parlementaire d'évaluation des choix scientifiques et technologiques (Sénat et Assemblée nationale)", '4 juin 2020, mise à jour le 18 juin 2020',
  'https://www.senat.fr/fileadmin/Fichiers/Images/opecst/quatre_pages/OPESCT_note_masques_covid.pdf',
  "Aucun essai randomisé n'a encore montré que le port généralisé du masque, indépendamment des autres mesures, ralentit les maladies respiratoires ; un essai danois est en cours. La note distingue « l'absence de preuve et la preuve d'absence d'efficacité ». Des études de laboratoire montrent que les masques chirurgicaux bloquent les gouttelettes de toux ; chez des patients grippés, ils réduisent l'émission de grosses particules d'un facteur 25 et des petites d'environ 3.",
  "Note scientifique parlementaire.", 'primaire'))
C_MAS_PSSTOCK = ('c_mas_psstock', src("Pénurie de masques : une responsabilité partagée par les gouvernements successifs", 'Public Sénat', '23 mars 2020 (mis à jour le 27 mars 2020)',
  'https://www.publicsenat.fr/article/politique/penurie-de-masques-une-responsabilite-partagee-par-les-gouvernements-successifs',
  "En 2010, l'État disposait d'environ 1,6 milliard de masques, dont 1 milliard de chirurgicaux et 600 millions de FFP2, selon Olivier Véran ; début 2020, il restait 150 millions de masques chirurgicaux et aucun FFP2. Le 26 février 2020, Jérôme Salomon déclarait au Sénat : « Il n'y a pas de sujet de pénurie ». Le gouvernement a diffusé des messages selon lesquels le masque n'était pas nécessaire pour le grand public et devait être réservé aux soignants.",
  "Chaîne parlementaire.", 'secondaire'))
C_MAS_PSNDIAYE = ('c_mas_psndiaye', src("« À aucun moment, on ne m'a demandé de mentir sur ce qu'était la situation des masques », déclare Sibeth Ndiaye", 'Public Sénat', '23 septembre 2020',
  'https://www.publicsenat.fr/actualites/politique/a-aucun-moment-on-ne-m-a-demande-de-mentir-sur-ce-qu-etait-la-situation-des',
  "Le 4 mars 2020, la porte-parole du gouvernement affirmait qu'il n'y avait « pas de risque de pénurie » de masques ; le 20 mars, elle déclarait : « Vous savez quoi, moi je ne sais pas utiliser un masque. » Devant la commission d'enquête du Sénat, le 23 septembre 2020, elle a reconnu des « phrases maladroites ».",
  "Chaîne parlementaire, compte rendu d'audition.", 'secondaire'))
C_MAS_PSVERAN = ('c_mas_psveran', src("Mea culpa d'Olivier Véran sur les masques : ce qu'avait déclaré le ministre devant les sénateurs", 'Public Sénat', '8 septembre 2022',
  'https://www.publicsenat.fr/actualites/non-classe/mea-culpa-d-olivier-veran-sur-les-masques-ce-qu-avait-declare-le-ministre-devant-les',
  "Olivier Véran : « La vérité, c'est que, sur les masques, nous nous sommes trompés, ni plus ni moins. » Le site du ministère indiquait plus tôt que le port du masque par la population non malade n'était pas recommandé car « son efficacité n'est pas démontrée ».",
  "Chaîne parlementaire.", 'secondaire'))

FICHES.append(fiche(
 id='masques-covid-inutiles', affirmation="Les masques ne servaient à rien contre le Covid.", volet='politique', sous_theme='Désinformation',
 mots_cles=['masques inutiles covid', 'le masque ne sert a rien', 'etude cochrane masques', 'masque covid efficacite', 'danmask', 'masques obligatoires inutiles', 'penurie de masques 2020', 'sibeth ndiaye masques', 'masque chirurgical covid', 'masque en tissu'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Les preuves sur le port du masque en population générale sont modestes et discutées, mais « modeste » ne veut pas dire « nul ». Le grand essai randomisé du Bangladesh trouve 11,2 % d'infections symptomatiques en moins avec des masques chirurgicaux, et 34,7 % chez les plus de 60 ans. La revue Cochrane de 2023, souvent citée, ne dit pas que les masques ne marchent pas : sa rédactrice en chef parle d'une lecture « inexacte et trompeuse ». En revanche, le gouvernement français a lui-même affirmé au printemps 2020, en pleine pénurie, que le masque n'était pas nécessaire pour le grand public.",
 contexte="L'idée s'est répandue après la publication d'une revue Cochrane en 2023, puis dans le rejet des obligations sanitaires. Elle s'appuie aussi sur un souvenir réel : au début de l'épidémie, le gouvernement disait que le masque ne servait pas au grand public, alors que les stocks avaient fondu.",
 explication="On distingue l'efficacité d'un masque bien porté, celle d'une politique de port généralisé, la qualité des essais disponibles et le discours des autorités françaises en 2020.",
 sources=[C_MAS_COCH, C_MAS_BGD, C_MAS_DAN, C_MAS_OMS, C_MAS_SPF, C_MAS_OPECST, C_MAS_PSSTOCK, C_MAS_PSNDIAYE, C_MAS_PSVERAN],
 faits=[
  fait("Selon Cochrane, dire que sa revue de 2023 montre que les masques ne marchent pas est « an inaccurate and misleading interpretation » : les résultats sur la promotion du masque étaient « inconclusive », et la revue ne pouvait pas dire si le port du masque lui-même réduit le risque.", 'c_mas_coch', '2023', 'Monde', "La revue la plus citée par les sceptiques conclut à une incertitude, pas à une inutilité.", 'etabli'),
  fait("Dans un essai randomisé mené dans 600 villages du Bangladesh auprès de 342 126 adultes, la promotion du masque a réduit la séroprévalence symptomatique de 9,3 % ; de 11,2 % dans les villages à masques chirurgicaux et de 34,7 % chez les 60 ans et plus de ces villages.", 'c_mas_bgd', '2020-2021', 'Bangladesh', "À grande échelle, avec seulement 42,3 % de port correct, l'effet est modeste mais réel, et plus net chez les plus âgés.", 'etabli', '11,2 %'),
  fait("Selon l'American College of Physicians, éditeur des Annals of Internal Medicine, dans l'essai danois DANMASK-19 sur 6 024 adultes, 1,8 % des porteurs de masque ont été infectés en un mois contre 2,1 % dans le groupe témoin ; l'essai ne mesurait pas la protection de l'entourage.", 'c_mas_dan', '2020', 'Danemark', "L'essai exclut une forte protection personnelle mais ne permet ni de conclure à l'absence d'effet, ni de juger le principal intérêt du masque : protéger les autres.", 'etabli', '1,8 %'),
  fait("Selon une note de l'Office parlementaire d'évaluation des choix scientifiques et technologiques de juin 2020, des études de laboratoire montrent que les masques chirurgicaux réduisent d'un facteur 25 l'émission de grosses particules chez des patients grippés, et il faut distinguer « l'absence de preuve et la preuve d'absence d'efficacité ».", 'c_mas_opecst', '2020', 'France', "Le mécanisme physique de protection de l'entourage est bien documenté.", 'etabli', '25'),
  fait("L'Organisation mondiale de la santé recommande le masque « as part of a comprehensive strategy » et précise que « the use of a mask alone is not sufficient ».", 'c_mas_oms', '2021', 'Monde', "Le masque n'a jamais été présenté par l'OMS comme une protection suffisante à lui seul, mais comme un outil parmi d'autres.", 'etabli'),
  fait("Fait défavorable : en mai 2020, Santé publique France écrivait que les études montrent « une réduction modérée cependant non significative » des infections respiratoires avec le masque en population générale, et que l'efficacité des masques en tissu « n'est pas acquise ».", 'c_mas_spf', '2020', 'France', "Les preuves en population générale étaient et restent limitées : il est honnête de le reconnaître.", 'etabli'),
  fait("Fait défavorable : selon Public Sénat, le gouvernement a lui-même affirmé début 2020 que le masque n'était pas nécessaire pour le grand public, alors que les stocks étaient passés d'environ 1,6 milliard de masques en 2010 à 150 millions de masques chirurgicaux et aucun FFP2 début 2020.", 'c_mas_psstock', '2010-2020', 'France', "Le doute sur les masques a été nourri par les autorités elles-mêmes, dans un contexte de pénurie qu'elles ne voulaient pas reconnaître.", 'etabli', '150 millions'),
  fait("Selon Public Sénat, Olivier Véran a reconnu en 2022 : « sur les masques, nous nous sommes trompés » ; la porte-parole Sibeth Ndiaye avait déclaré le 20 mars 2020 : « moi je ne sais pas utiliser un masque ».", 'c_mas_psveran', '2020-2022', 'France', "Le revirement du gouvernement explique en partie la méfiance actuelle, mais il portait sur l'utilité du masque, pas sur sa prétendue inutilité.", 'etabli'),
 ],
 court="Non, les masques n'étaient pas inutiles, mais leur effet est modeste. Au Bangladesh, sur 342 126 adultes, les masques chirurgicaux ont réduit les infections symptomatiques de 11,2 %, et de 34,7 % chez les plus de 60 ans. La revue Cochrane conclut à l'incertitude, pas à l'inutilité. Le doute vient aussi du gouvernement, qui disait en 2020, en pleine pénurie, que le masque n'était pas nécessaire au grand public.",
 moyen="Les preuves sur le masque en population générale sont moins solides qu'on l'a parfois dit, mais elles ne disent pas qu'il ne sert à rien. Le plus grand essai randomisé, au Bangladesh, trouve 11,2 % d'infections symptomatiques en moins avec des masques chirurgicaux, et 34,7 % chez les plus de 60 ans. L'essai danois DANMASK-19 exclut une forte protection personnelle, mais ne mesurait pas la protection de l'entourage, qui est le rôle principal du masque.\n\nLa revue Cochrane de 2023, brandie comme une preuve, conclut à des résultats « non concluants » ; Cochrane a qualifié de « trompeuse » la lecture « les masques ne marchent pas ». Le soupçon a aussi une origine politique : début 2020, alors que les stocks étaient tombés à 150 millions de masques chirurgicaux, le gouvernement expliquait que le masque n'était pas nécessaire pour le grand public, avant de changer de discours. Olivier Véran a reconnu ensuite : « nous nous sommes trompés ».",
 detaille="Il faut d'abord distinguer deux questions. Un masque bien porté retient-il les gouttelettes et les particules ? Oui : la note de l'Office parlementaire d'évaluation des choix scientifiques de juin 2020 rappelle que les masques chirurgicaux réduisent fortement l'émission de particules chez des malades. Une politique de port du masque dans toute la population réduit-elle les contaminations ? C'est plus difficile à mesurer, car tout dépend de la façon dont les gens le portent et de ce qu'ils font par ailleurs.\n\nLes essais randomisés donnent une réponse nuancée. Au Bangladesh, dans 600 villages et sur 342 126 adultes, une campagne de distribution a fait passer le port correct de 13,3 % à 42,3 % et réduit la séroprévalence symptomatique de 9,3 % ; avec des masques chirurgicaux, de 11,2 %, et de 34,7 % chez les plus de 60 ans. Au Danemark, l'essai DANMASK-19 sur 6 024 adultes trouve 1,8 % d'infections chez les porteurs de masque contre 2,1 % chez les autres : il exclut une protection personnelle forte, sans exclure un effet plus modeste, et il ne mesurait pas la protection de l'entourage.\n\nLa revue Cochrane de 2023 a été largement présentée comme la preuve que les masques ne servent à rien. Sa rédactrice en chef a répondu que cette lecture était « inexacte et trompeuse » : les résultats étaient non concluants, à cause du risque de biais des essais, et la revue ne pouvait pas répondre à la question de l'efficacité du port du masque lui-même. L'OMS, de son côté, n'a jamais présenté le masque comme suffisant seul, mais comme une mesure parmi d'autres.\n\nReste un fait qui donne prise au soupçon. En mars 2020, la France manquait de masques : les stocks étaient passés d'environ 1,6 milliard en 2010 à 150 millions de masques chirurgicaux. Le ministère écrivait que l'efficacité du masque pour la population non malade « n'est pas démontrée », et la porte-parole du gouvernement disait ne pas savoir l'utiliser. Le discours a ensuite changé du tout au tout. Olivier Véran a reconnu en 2022 : « nous nous sommes trompés ». La leçon est politique : quand un gouvernement adapte le discours scientifique à ses pénuries, il fabrique la défiance.",
 empathie="On a beaucoup demandé aux gens pendant l'épidémie, parfois avec des consignes contradictoires, et certains ont eu l'impression qu'on leur mentait. Ce sentiment a des raisons réelles, à commencer par les déclarations du gouvernement en mars 2020.",
 legitimes=["Les essais en population générale montrent des effets modestes, et certains ne sont pas concluants.", "Le gouvernement a dit au printemps 2020 que le masque n'était pas nécessaire pour le grand public, en pleine pénurie.", "L'efficacité des masques en tissu n'était pas démontrée, selon Santé publique France en 2020."],
 contre=[
  ("La revue Cochrane a prouvé que les masques ne marchent pas.", "Cochrane a répondu elle-même que cette lecture était « inexacte et trompeuse » : sa revue conclut à des résultats non concluants, pas à une inutilité."),
  ("Le gouvernement disait lui-même qu'ils ne servaient à rien.", "C'est vrai, et c'était une erreur reconnue par Olivier Véran : à l'époque, les stocks étaient tombés à 150 millions de masques chirurgicaux. Cela montre une mauvaise gestion, pas l'inutilité du masque."),
  ("Au Danemark, l'étude n'a rien trouvé.", "Elle trouve 1,8 % d'infections contre 2,1 % et exclut seulement une forte protection personnelle ; elle ne mesurait pas la protection des autres, qui est l'intérêt principal du masque."),
 ],
 questions=["Si le masque ne servait à rien, pourquoi les soignants le portent-ils depuis toujours ?", "Un effet modeste mais réel, chez les plus âgés notamment, vaut-il le coût de porter un masque en période d'épidémie ?"],
 limites=["L'essai du Bangladesh a été lu à travers le résumé du document de travail de Yale révisé en mai 2022 ; sa publication dans la revue Science n'a pas été vérifiée ici.", "L'essai DANMASK-19 a été lu à travers le communiqué de l'éditeur ; la revue Cochrane elle-même n'a pas été ouverte, seule la déclaration de Cochrane l'a été.", "La note de l'OPECST et la synthèse de Santé publique France datent de 2020 et ne tiennent pas compte des essais ultérieurs.", "Les essais mesurent des politiques de port du masque, avec un port réel partiel : ils ne mesurent pas l'efficacité d'un masque porté correctement en permanence.", "L'expression exacte « masques inutiles » n'a pas été retrouvée dans les sources lues : le discours gouvernemental est rapporté par Public Sénat (« pas nécessaire », « efficacité n'est pas démontrée »)."],
 publics={'convaincus': "Tu as raison sur un point : le gouvernement a dit en 2020 que le masque n'était pas nécessaire pour le grand public, alors que les stocks étaient tombés à 150 millions. Mais la revue Cochrane que l'on cite dit seulement que les résultats sont incertains, et le plus grand essai, au Bangladesh, trouve 11,2 % d'infections en moins avec des masques chirurgicaux. Modeste, oui ; inutile, non.",
  'indecis': "Les preuves sur le masque en population générale sont modestes : il ne protège pas à lui seul, et l'OMS l'a toujours présenté comme une mesure parmi d'autres. Mais les essais montrent un effet réel, plus net chez les personnes âgées. Les consignes contradictoires de 2020 venaient surtout d'une pénurie, reconnue ensuite comme une erreur."},
 a_actualiser='2027-11-30', raison="Nouvelles revues systématiques sur les interventions non pharmaceutiques et conclusions des travaux sur la préparation aux pandémies.",
))


# 5 ── « Les vaccins provoquent l'autisme. » ──────────────
C_AUT_CIDRAP = ('c_aut_cidrap', src("Report says 1998 vaccine-autism study was fraud", 'Robert Roos, CIDRAP (université du Minnesota)', '6 janvier 2011',
  'https://www.cidrap.umn.edu/public-health/report-says-1998-vaccine-autism-study-was-fraud',
  "L'article de 1998 dans The Lancet, dont Andrew Wakefield était le premier auteur, décrivait 12 enfants et liait le vaccin rougeole-oreillons-rubéole à un syndrome associant entérocolite et autisme régressif. Le General Medical Council l'a censuré en janvier 2010 ; The Lancet a rétracté l'article en février 2010 ; Wakefield a ensuite perdu le droit d'exercer au Royaume-Uni. Le 5 janvier 2011, le BMJ publie l'enquête du journaliste Brian Deer et un éditorial qualifiant l'étude d'« elaborate fraud » : trois des neuf enfants présentés comme atteints d'autisme régressif n'avaient pas ce diagnostic ; cinq des douze avaient des troubles du développement préexistants ; l'étude avait été financée en vue d'un procès, un avocat ayant versé plus de 600 000 dollars à Wakefield.",
  "Centre universitaire de recherche et d'information sur les maladies infectieuses.", 'secondaire'))
C_AUT_STAT = ('c_aut_stat', src("It's old news that vaccines don't cause autism. But a major new study aims to refute skeptics again", 'Helen Branswell, STAT', '4 mars 2019',
  'https://www.statnews.com/2019/03/04/vaccines-no-association-autism-major-study/',
  "Étude du Statens Serum Institut publiée dans Annals of Internal Medicine sur 657 461 enfants danois nés entre 1999 et 2010 : aucune association entre le vaccin rougeole-oreillons-rubéole et l'autisme, y compris chez les enfants considérés « à risque », par exemple ceux ayant un frère ou une sœur autiste, et pas de regroupement des diagnostics après la vaccination. Une étude de 2002 dans le New England Journal of Medicine portait déjà sur 537 303 enfants danois. Les auteurs : « We found no support for the hypothesis of increased risk for autism after MMR vaccination ».",
  "Média de référence en santé, rendant compte d'une étude publiée dans une revue à comité de lecture.", 'secondaire'))
C_AUT_SSI = ('c_aut_ssi', src("Large Danish study: No link between vaccines and autism or 49 other health conditions", 'Statens Serum Institut (Danemark), sur une étude publiée dans Annals of Internal Medicine', '15 juillet 2025',
  'https://en.ssi.dk/news/news/2025/large-danish-study-no-link-between-vaccines-and-autism-or-49-other-health-conditions',
  "Étude de cohorte nationale (Andersson et al., « Aluminum-adsorbed vaccines and chronic diseases in childhood ») portant sur plus d'un million d'enfants danois nés de 1997 à 2018 : aucun lien statistique significatif entre l'aluminium des vaccins de l'enfance et 50 affections, dont l'autisme, l'asthme, les allergies et les maladies auto-immunes. Anders Hviid : « This is the first study of this scale and with such comprehensive analyses ».",
  "Institut public danois de santé, communiqué sur une étude publiée dans une revue à comité de lecture.", 'etude'))
