FICHES.append(fiche(
 id='loi-sru-logements-sociaux', affirmation="La loi SRU oblige les villes à construire des HLM pour des cas sociaux.", volet='social', sous_theme='Aides au logement',
 mots_cles=['loi sru', 'hlm cas sociaux', 'logements sociaux obligatoires', '25 % logements sociaux', 'communes carencees', 'qui vit en hlm', 'plafonds hlm', 'amende sru', 'mixite sociale', 'demandeurs logement social'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. La loi SRU impose bien à environ 2 100 communes de viser 20 ou 25 % de logements sociaux, mais ces logements ne sont pas réservés à des « cas sociaux » : environ 70 % des ménages de métropole y sont éligibles et près de 2,9 millions de ménages attendent un HLM. Les locataires du parc social sont souvent modestes (34 % sont pauvres), justement parce que l'offre manque. Et de nombreuses communes préfèrent payer des pénalités plutôt que construire.",
 contexte="L'article 55 de la loi SRU de 2000 est régulièrement attaqué par des élus de droite et d'extrême droite, qui y voient une obligation d'accueillir « la misère » dans leur commune. Le bilan triennal 2020-2022 a montré un net recul de la construction.",
 explication="On distingue ce que la loi exige, qui peut habiter un logement social (plafonds de ressources), qui y vit réellement, et la façon dont les communes appliquent ou contournent la loi.",
 sources=[E_SRU_ART55, E_SRU_BILAN, E_SRU_LOCALTIS, E_SRU_ANCOLS, E_SRU_SDES, E_SRU_INSEE, E_SRU_USH],
 faits=[
  fait("Selon le ministère chargé du Logement, l'article 55 de la loi SRU impose aux communes de plus de 3 500 habitants (1 500 en agglomération parisienne) situées dans de grandes agglomérations d'atteindre 25 % de logements sociaux, ou 20 % dans les territoires moins tendus.", 'e_sru_art55', 'depuis 2000', 'France', "La loi fixe un objectif de répartition du logement social entre communes, pas une obligation de loger une catégorie particulière.", 'etabli', '25 %'),
  fait("Selon le bilan officiel 2020-2022, environ 2 100 communes sont soumises à la loi SRU ; 711 n'ont pas atteint leurs objectifs et 341 ont été déclarées carencées.", 'e_sru_bilan', '2020-2022', 'France', "Un tiers des communes concernées ne tient pas ses engagements.", 'etabli', '341'),
  fait("Selon une étude de l'Ancols rapportée par Localtis, environ 70 % des ménages de France métropolitaine, soit 20 millions sur 28 millions, sont éligibles au logement social au plafond le plus élevé ; 35 % des ménages sont des propriétaires éligibles.", 'e_sru_ancols', '2024', 'France métropolitaine', "Le logement social s'adresse à la grande majorité de la population, salariés et classes moyennes compris.", 'estimation', '70 %'),
  fait("Selon l'Union sociale pour l'habitat, citée par Maire info, près de 2,9 millions de ménages attendaient un logement social début 2026, un record, pour environ 390 000 attributions en 2025.", 'e_sru_ush', '2025', 'France', "La demande dépasse très largement l'offre : construire des logements sociaux répond à un besoin massif.", 'estimation', '2,9 millions'),
  fait("Selon le SDES, 5,3 millions de ménages, soit 17,6 % des ménages, sont locataires du parc social ; leur revenu moyen par unité de consommation était de 13 100 euros en 2017, contre 18 500 euros dans le parc privé.", 'e_sru_sdes', '2017-2021', 'France', "Les locataires HLM sont plus modestes que la moyenne, mais ce sont des ménages ordinaires, une famille sur six.", 'etabli', '17,6 %'),
  fait("Fait défavorable : selon l'Insee, en 2022, 34 % des ménages du parc social vivaient sous le seuil de pauvreté, contre 14 % de la population, et dans les quartiers où plus de la moitié des logements sont sociaux, le taux de pauvreté atteint 30 %.", 'e_sru_insee', '2022', 'France', "La pauvreté est bien plus concentrée dans le parc social et dans certains quartiers : c'est précisément ce que la loi SRU cherche à corriger en répartissant les logements sociaux dans toutes les communes.", 'etabli', '34 %'),
  fait("Fait défavorable : selon le ministère, le prélèvement brut sur les communes déficitaires atteignait 240 millions d'euros en 2024, ramené à 141 millions après déduction de leurs dépenses en faveur du logement social.", 'e_sru_art55', '2024', 'France', "Beaucoup de communes préfèrent payer plutôt que construire : la sanction existe, mais elle ne suffit pas à faire appliquer la loi.", 'etabli', '240 millions d’euros'),
  fait("Fait défavorable : selon Localtis, seules 311 communes (30 %) ont rempli tous leurs objectifs sur 2020-2022, 141 communes ont été carencées plus de trois fois, et 185 651 logements sociaux ont été construits pour un objectif de 276 508.", 'e_sru_localtis', '2020-2022', 'France', "La loi est largement contournée, ce qui affaiblit son effet sur la mixité.", 'etabli', '311'),
 ],
 court="La loi SRU demande à environ 2 100 communes de viser 20 ou 25 % de logements sociaux. Ce ne sont pas des logements pour « cas sociaux » : environ 70 % des ménages y sont éligibles et près de 2,9 millions attendent un HLM. Le vrai problème, ce sont les communes qui préfèrent payer des pénalités.",
 moyen="L'article 55 de la loi SRU impose aux communes urbaines d'avoir 25 % de logements sociaux, ou 20 % là où la demande est moins forte. Environ 2 100 communes sont concernées. Le logement social n'est pas réservé aux plus pauvres : selon l'Ancols, environ 70 % des ménages de métropole respectent les plafonds de ressources les plus élevés, et près de 2,9 millions de ménages sont en attente.\n\nLes locataires HLM sont plus modestes que la moyenne : selon l'Insee, 34 % vivent sous le seuil de pauvreté, et la pauvreté se concentre dans les quartiers où le parc social domine. C'est justement pour éviter ces ghettos que la loi oblige toutes les communes à prendre leur part. Or sur 2020-2022, 711 communes n'ont pas tenu leurs objectifs et 341 ont été carencées.",
 detaille="La loi SRU de 2000 a été pensée contre la ségrégation urbaine. Son article 55 demande aux communes de plus de 3 500 habitants (1 500 en agglomération parisienne) situées dans de grandes agglomérations d'atteindre 25 % de logements sociaux parmi leurs résidences principales, ou 20 % là où la demande est moins forte. Les communes en retard doivent rattraper une partie de leur déficit tous les trois ans ; sinon, elles paient un prélèvement annuel et peuvent être déclarées « carencées » par le préfet.\n\nQui a droit à un logement social ? Bien plus de monde qu'on ne le croit. Selon une étude de l'Ancols, environ 70 % des ménages de France métropolitaine, soit 20 millions, sont sous le plafond de ressources le plus élevé, dont beaucoup de propriétaires. Selon l'Union sociale pour l'habitat, près de 2,9 millions de ménages attendaient un logement social début 2026, pour environ 390 000 attributions par an. Les locataires actuels, 17,6 % des ménages selon le SDES, sont plus modestes que la moyenne : revenu moyen par unité de consommation de 13 100 euros en 2017 contre 18 500 euros dans le parc privé.\n\nIl est vrai que la pauvreté est concentrée dans le parc social : selon l'Insee, 34 % de ses ménages sont pauvres, et le taux de pauvreté atteint 30 % dans les quartiers où plus de la moitié des logements sont sociaux. Mais c'est la conséquence d'une offre trop rare, attribuée en priorité aux plus fragiles, et concentrée dans certaines villes. La loi SRU vise exactement l'inverse : répartir les logements sociaux partout pour que l'infirmière, le livreur ou le retraité modeste puissent habiter aussi dans les communes aisées.\n\nLe bilan reste décevant. Sur 2020-2022, seules 311 communes ont rempli tous leurs objectifs, 341 ont été carencées, dont 141 plus de trois fois, et en Provence-Alpes-Côte d'Azur 157 communes sur 165 étaient en défaut. En 2024, les prélèvements ont atteint 240 millions d'euros bruts : certaines communes préfèrent payer que construire. Le débat n'est donc pas « des HLM pour des cas sociaux », mais la volonté politique de loger dignement la majorité de la population.",
 empathie="On peut craindre que l'arrivée de logements sociaux change le visage de son quartier ou fasse baisser la valeur de son bien. Ces inquiétudes méritent une réponse, car elles reposent souvent sur une image du HLM qui ne correspond pas à ceux qui y vivent ou qui l'attendent.",
 legitimes=["La concentration de la pauvreté dans certains grands ensembles est un vrai problème, reconnu par l'Insee.", "Certaines communes manquent réellement de foncier, et la loi prévoit des exemptions dans ces cas.", "Les élus locaux doivent pouvoir peser sur les projets et sur les attributions."],
 contre=[
  ("Ces logements sont pour des gens qui ne travaillent pas.", "Environ 70 % des ménages sont éligibles, beaucoup de salariés et de retraités attendent un HLM, et 2,9 millions de ménages sont sur liste d'attente."),
  ("Les maires qui refusent ont raison de protéger leur ville.", "Ils protègent surtout l'entre-soi : en payant des pénalités, ils laissent d'autres communes concentrer la pauvreté qu'ils reprochent ensuite aux HLM."),
 ],
 questions=["Ton enfant, ou tes parents à la retraite, rentreraient-ils dans les plafonds HLM ?", "Si les logements sociaux étaient mieux répartis, les quartiers les plus pauvres ne seraient-ils pas moins ghettoïsés ?"],
 limites=["Le chiffre de 70 % de ménages éligibles provient d'une étude de l'Ancols lue à travers un article de Localtis ; l'étude elle-même n'a pas été ouverte.", "Les revenus des locataires du SDES datent de 2017.", "Le nombre de demandeurs (2,9 millions) est rapporté par Maire info d'après l'Union sociale pour l'habitat ; il s'agit de ménages demandeurs, pas de personnes.", "Le bilan triennal 2023-2025 n'était pas encore publié lors de la rédaction.", "La page de synthèse du gouvernement sur la crise du logement (info.gouv.fr) n'a pas pu être ouverte."],
 publics={'convaincus': "Tu crois que les HLM, c'est pour les « cas sociaux » ? Environ 70 % des ménages y ont droit, et 2,9 millions attendent un logement, souvent des gens qui travaillent. Les maires qui refusent d'en construire paient des pénalités et laissent la pauvreté se concentrer ailleurs : c'est ça qui fabrique les ghettos.",
  'indecis': "La loi SRU demande aux communes urbaines d'avoir 20 ou 25 % de logements sociaux. Les inquiétudes sur la concentration de la pauvreté sont fondées, mais la loi vise justement à mieux répartir. Le logement social concerne la majorité des ménages : c'est un outil pour loger les classes populaires et moyennes là où elles travaillent."},
 a_actualiser='2027-06-30', raison="Publication du bilan triennal SRU 2023-2025 et nouveaux chiffres de la demande de logement social.",
))

