FICHES.append(fiche(
 id='panneaux-solaires-recyclage', affirmation="Les panneaux solaires ne sont pas recyclables.", volet='ecologie', sous_theme='Énergies renouvelables',
 mots_cles=['panneaux solaires recyclables', 'recyclage panneaux photovoltaiques', 'dechets panneaux solaires', 'solaire pas ecologique', 'soren recyclage', 'panneaux solaires chinois', 'fin de vie panneaux solaires', 'silicium argent recyclage', 'photovoltaique pollution'],
 verdict='contredit', fiabilite='etabli',
 resume="Faux. En France, les panneaux usagés sont collectés gratuitement par une filière agréée : en 2025, près de 13 760 tonnes ont été collectées et plus de 90 % de leur masse a été valorisée, principalement le verre et l'aluminium. La vraie limite est ailleurs : les matériaux les plus précieux, comme l'argent et le silicium, sont encore mal récupérés, et la fabrication reste dominée à plus de 80 % par la Chine.",
 contexte="L'idée circule pour discréditer l'énergie solaire, souvent avec l'image de montagnes de panneaux enfouis. Elle mélange des problèmes réels (dépendance industrielle, matériaux critiques) et une affirmation fausse sur le recyclage.",
 explication="On regarde ce que la filière française collecte et traite réellement, ce que contient un panneau, ce qui reste difficile à récupérer et d'où viennent les panneaux.",
 sources=[E_PV_SOREN, E_PV_TI, E_PV_ADEME, E_PV_BEI, E_PV_AIE],
 faits=[
  fait("Selon l'ADEME, les panneaux photovoltaïques usagés suivent la filière des équipements électriques et électroniques ; leurs métaux, leur verre et leurs plastiques sont récupérés, et Soren est l'organisme agréé par les pouvoirs publics pour leur collecte et leur recyclage.", 'e_pv_ademe', '2026', 'France', "Une filière légale de collecte et de recyclage existe : un panneau n'est pas un déchet sans issue.", 'etabli'),
  fait("Selon son rapport d'activité, Soren a collecté près de 13 760 tonnes de panneaux en 2025 ; 10 684 tonnes ont été recyclées (83,89 %), 10,19 % ont fait l'objet d'une valorisation énergétique et 5,92 % ont été éliminés.", 'e_pv_soren', '2025', 'France', "Plus de 90 % de la masse traitée est valorisée, dont l'essentiel sous forme de matière.", 'etabli', '13 760 tonnes'),
  fait("Selon le directeur général de Soren, interrogé par Techniques de l'Ingénieur, le verre et l'aluminium représentent 85 % du poids d'un panneau et le taux de valorisation en masse est « de l'ordre de 92 à 94 % ».", 'e_pv_ti', '2025', 'France', "Les matériaux les plus lourds d'un panneau sont des matériaux banals, faciles à recycler.", 'estimation', '85 %'),
  fait("Selon la même source, la collecte est passée de 366 tonnes en 2015 à 9 477 tonnes en 2024, avec un taux de collecte d'environ 77 % pour un objectif européen de 85 %.", 'e_pv_ti', '2015-2024', 'France', "La filière monte en puissance mais ne récupère pas encore tous les panneaux en fin de vie.", 'estimation', '77 %'),
  fait("Fait défavorable : selon le directeur général de Soren, silicium, cuivre et argent représentent environ 40 % de la valeur matière d'un panneau mais une « infime part du poids », et ces fractions sont difficiles à extraire avec les procédés classiques.", 'e_pv_ti', '2023-2025', 'France et Europe', "Le recyclage « en masse » est élevé, mais le recyclage « en valeur » des métaux critiques reste à développer, avec des procédés comme celui de la jeune entreprise ROSI.", 'estimation', '40 %'),
  fait("Selon la Banque européenne d'investissement, le recyclage courant vise surtout le cadre en aluminium, la boîte de jonction et parfois le verre ; la jeune entreprise française ROSI, choisie par Soren, dit pouvoir récupérer silicium, argent, aluminium, cuivre et verre de qualité.", 'e_pv_bei', '2023', 'France et Europe', "Des procédés plus fins existent et commencent à être déployés pour récupérer les matériaux de valeur.", 'estimation'),
  fait("Fait défavorable : selon l'Agence internationale de l'énergie, la part de la Chine dépasse 80 % dans toutes les étapes clés de fabrication des panneaux, et la province du Xinjiang représente 40 % de la production mondiale de polysilicium.", 'e_pv_aie', '2022', 'Monde', "La critique de la dépendance industrielle à la Chine est fondée ; elle plaide pour relocaliser la fabrication et le recyclage, pas pour renoncer au solaire.", 'etabli', '80 %'),
  fait("Selon Soren, près de 180 000 tonnes de panneaux seront à traiter en 2040 ; selon Techniques de l'Ingénieur, les panneaux durent 25 à 30 ans et le gros des volumes arrivera entre 2030 et 2040.", 'e_pv_soren', '2025-2040', 'France', "Le défi est d'anticiper : il faut investir dès maintenant dans des usines capables de récupérer argent et silicium.", 'estimation', '180 000 tonnes'),
 ],
 court="Faux : en France, une filière agréée collecte les panneaux usagés. En 2025, près de 13 760 tonnes ont été collectées et plus de 90 % de leur masse valorisée, surtout le verre et l'aluminium. La vraie faiblesse, c'est la récupération de l'argent et du silicium, et une fabrication à plus de 80 % chinoise.",
 moyen="Un panneau solaire est surtout fait de verre et d'aluminium : 85 % de son poids, selon l'éco-organisme Soren. Ces matériaux se recyclent bien. En 2025, Soren a collecté près de 13 760 tonnes de panneaux, dont 10 684 tonnes ont été recyclées, et plus de 90 % de la masse a été valorisée. L'ADEME rappelle que les panneaux suivent la filière des équipements électriques et électroniques.\n\nLes limites sont réelles. Les matériaux les plus précieux, argent, cuivre et silicium, pèsent peu mais font environ 40 % de la valeur, et ils sont encore difficiles à extraire. Et selon l'Agence internationale de l'énergie, plus de 80 % de la fabrication mondiale est chinoise. La réponse est de développer un recyclage de valeur et de relocaliser l'industrie, pas de renoncer au solaire.",
 detaille="Dire que les panneaux solaires « ne sont pas recyclables » est faux. En France, selon l'ADEME, ils relèvent de la filière des déchets d'équipements électriques et électroniques, et un organisme agréé par les pouvoirs publics, Soren, collecte les panneaux usagés, notamment via 323 points d'apport volontaire. En 2025, près de 13 760 tonnes ont été collectées ; 10 684 tonnes ont été recyclées, 10,19 % ont été valorisées sous forme d'énergie et seulement 5,92 % éliminées.\n\nCe chiffre s'explique par la composition d'un panneau : le verre et l'aluminium représentent 85 % de son poids, selon le directeur général de Soren, et se recyclent facilement. Mais ce recyclage « de masse » ne dit pas tout. Les métaux critiques, silicium, cuivre et argent, ne pèsent presque rien (l'argent 0,08 % du total) mais font environ 40 % de la valeur matière. La Banque européenne d'investissement relevait en 2023 que le recyclage courant visait surtout le cadre, la boîte de jonction et parfois le verre. Des procédés plus fins, comme celui de la jeune entreprise française ROSI, choisie par Soren, cherchent à récupérer silicium et argent.\n\nLa filière doit encore grandir : la collecte est passée de 366 tonnes en 2015 à 9 477 tonnes en 2024, avec un taux de collecte d'environ 77 % pour un objectif européen de 85 %. Comme les panneaux durent 25 à 30 ans, près de 180 000 tonnes seront à traiter en 2040 selon Soren. C'est maintenant qu'il faut investir dans les usines de recyclage.\n\nLa critique la plus solide porte sur l'industrie : selon l'Agence internationale de l'énergie, la Chine assure plus de 80 % de toutes les étapes de fabrication, et le Xinjiang produit à lui seul 40 % du polysilicium mondial. Ce constat appelle une politique industrielle publique : relocaliser la production, imposer des normes sociales et environnementales, et faire du recyclage une source de matières premières en Europe.",
 empathie="On a raison de vouloir savoir ce que deviennent les panneaux après 25 ou 30 ans : une énergie « verte » qui laisserait des montagnes de déchets ne le serait pas vraiment. La question mérite une réponse chiffrée.",
 legitimes=["La récupération de l'argent et du silicium reste limitée et coûteuse.", "La fabrication des panneaux est massivement chinoise, avec des questions sur les conditions de production.", "Le taux de collecte reste inférieur à l'objectif européen."],
 contre=[
  ("Le taux de 90 %, c'est juste du verre broyé.", "C'est en partie vrai : la valeur se trouve dans les métaux critiques. Mais le verre et l'aluminium recyclés évitent de produire de la matière neuve, et la filière développe des procédés pour l'argent et le silicium."),
  ("Les panneaux finissent en décharge en Afrique.", "En France, les panneaux collectés sont traités par une filière agréée et seuls 5,92 % ont été éliminés en 2025. Le risque concerne les panneaux qui échappent à la collecte, d'où l'enjeu d'atteindre l'objectif de 85 %."),
 ],
 questions=["Sais-tu qu'il existe des points de collecte agréés pour les panneaux solaires usagés ?", "Plutôt que de renoncer au solaire, ne faudrait-il pas fabriquer et recycler les panneaux en Europe ?"],
 limites=["Les chiffres de collecte et de recyclage viennent de Soren, organisme chargé de la filière, donc partie prenante ; aucun audit indépendant n'a été lu.", "Le rapport de l'AIE date de 2022 ; la part chinoise a pu encore augmenter.", "La date exacte d'entrée des panneaux dans la filière DEEE (2014) n'a pas pu être vérifiée sur un texte officiel (pages Légifrance et Ineris non ouvertes).", "Le document « Vrai/Faux sur l'énergie solaire » du ministère et la page ministérielle sur les panneaux usagés n'ont pas pu être ouverts.", "Le taux de collecte de 77 % est une estimation donnée par le dirigeant de Soren."],
 publics={'convaincus': "On t'a dit que les panneaux finissent tous à la décharge ? En 2025, la filière française en a collecté près de 13 760 tonnes et valorisé plus de 90 % de la masse. Ce qui est vrai, c'est que la fabrication est à plus de 80 % chinoise : ça plaide pour produire et recycler en France, pas pour abandonner le solaire.",
  'indecis': "Les panneaux solaires sont recyclables : leur verre et leur aluminium, 85 % du poids, sont bien récupérés par une filière agréée. Le point faible, ce sont les métaux précieux comme l'argent et le silicium, encore mal extraits, et la dépendance à la Chine. Ce sont des chantiers industriels à mener, pas des raisons de rejeter le solaire."},
 a_actualiser='2027-07-31', raison="Rapport d'activité 2026 de Soren et évolution des procédés de récupération de l'argent et du silicium.",
))

